1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12		"time"
13	)
14	
15	// 数据目录布局：
16	//
17	//	<dir>/state.json      全部业务数据（客户、用量、账单、封账状态）
18	//	<dir>/state.json.tmp  原子写入临时文件（保存后 rename 覆盖）
19	//
20	// 所有命令顺序运行，单次调用内完成“读入—修改—整体原子落盘”，
21	// 因此账单与封账状态在同一次保存中持久化，不会出现半写状态。
22	
23	const stateVersion = 1
24	
25	type customer struct {
26		ID     string `json:"id"`
27		Name   string `json:"name"`
28		Price  int64  `json:"price_fen"`         // 固定单价，非负整数分，创建后不可修改
29		PlanID string `json:"plan_id,omitempty"` // 绑定的阶梯计费方案标识；空表示固定单价客户，创建后不可变更
30	}
31	
32	// tier 是阶梯计费方案中的一档：Limit 为月累计数量上限（正整数），
33	// 仅最后一档无上限（Limit 为 0）；Price 为该档每单位价格（非负整数分）。
34	type tier struct {
35		Limit int64 `json:"limit"`     // 累计数量上限；0 表示无上限（仅最后一档）
36		Price int64 `json:"price_fen"` // 每单位价格，非负整数分，可升可降
37	}
38	
39	// plan 是按月累计用量的阶梯计费方案：标识唯一非空、名称非空、固定月费
40	// （非负整数分，省略视为 0）与至少一档有序阶梯；月费与规则创建后不可修改。
41	type plan struct {
42		ID         string `json:"id"`
43		Name       string `json:"name"`
44		MonthlyFee int64  `json:"monthly_fee_fen,omitempty"` // 固定月费，非负整数分；每账期收取一次整月，不按天折算
45		Tiers      []tier `json:"tiers"`                     // 至少一档；有限上限严格递增，最后一档无上限
46	}
47	
48	type usageRecord struct {
49		ID         string `json:"id"`
50		CustomerID string `json:"customer_id"`
51		Time       string `json:"time"` // RFC3339，保留原始输入用于去重判定
52		Quantity   int64  `json:"quantity"`
53	}
54	
55	// lineSegment 是阶梯计费下一条用量记录落入某一档的分段：数量与小计；
56	// 该档单价由账单保存的方案规则按档位序号取得。
57	type lineSegment struct {
58		Tier     int   `json:"tier"`     // 档位序号（0 起，对应账单保存的方案规则）
59		Quantity int64 `json:"quantity"` // 落入本档的数量
60		Fee      int64 `json:"fee_fen"`  // 本分段小计（数量 × 该档单价）
61	}
62	
63	// tierTotal 是阶梯账单中某一档的合计数量与金额（与 PlanTiers 顺序对齐）。
64	type tierTotal struct {
65		Quantity int64 `json:"quantity"`
66		Fee      int64 `json:"fee_fen"`
67	}
68	
69	type billLine struct {
70		UsageID  string        `json:"usage_id"`
71		Time     string        `json:"time"`
72		Quantity int64         `json:"quantity"`
73		LineFee  int64         `json:"line_fee_fen"`
74		Segments []lineSegment `json:"segments,omitempty"` // 阶梯账单：本条用量的跨档分段
75	}
76	
77	type bill struct {
78		ID         string      `json:"id"`
79		CustomerID string      `json:"customer_id"`
80		Month      string      `json:"month"`                 // YYYY-MM（UTC）
81		Pricing    string      `json:"pricing,omitempty"`     // 计价类型：空或 fixed 为固定单价；tiered 为阶梯计费
82		PlanID     string      `json:"plan_id,omitempty"`     // 阶梯账单：方案标识
83		PlanName   string      `json:"plan_name,omitempty"`   // 阶梯账单：方案名称（快照）
84		PlanTiers  []tier      `json:"plan_tiers,omitempty"`  // 阶梯账单：完整方案规则（快照）
85		TierTotals []tierTotal `json:"tier_totals,omitempty"` // 阶梯账单：各档实际数量与金额合计
86		// 阶梯账单：实际收取的固定月费快照（分），非负；按账期有效方案收取一次
87		// 整月，不计入总数量、各档金额或逐条小计。固定单价账单恒为 0。
88		MonthlyFee int64      `json:"monthly_fee_fen,omitempty"`
89		TotalQty   int64      `json:"total_quantity"`
90		UnitPrice  int64      `json:"unit_price_fen"` // 固定单价账单的单价；阶梯账单恒为 0（不伪造统一单价）
91		TotalFee   int64      `json:"total_fee_fen"`
92		Lines      []billLine `json:"lines"`
93		CreatedAt  string     `json:"created_at"`
94	}
95	
96	// adjustment 是对已结算账单的一次费用调整（正数补收、负数减免）。
97	// 记录一旦写入永不删除；撤销只是追加撤销信息，保留原记录。
98	type adjustment struct {
99		ID           string `json:"id"`
100		CustomerID   string `json:"customer_id"`
101		Month        string `json:"month"` // YYYY-MM（UTC），与所属账单一致
102		Amount       int64  `json:"amount_fen"`
103		Reason       string `json:"reason"`
104		Seq          int64  `json:"seq"` // 全局递增操作序号，决定历史展示顺序
105		CreatedAt    string `json:"created_at"`
106		Revoked      bool   `json:"revoked"`
107		RevokeReason string `json:"revoke_reason,omitempty"`
108		RevokeSeq    int64  `json:"revoke_seq,omitempty"`
109		RevokedAt    string `json:"revoked_at,omitempty"`
110	}
111	
112	// paymentAllocation 是一笔收款在某个已结算月份上的分配（正整数分）。
113	type paymentAllocation struct {
114		Month  string `json:"month"`      // YYYY-MM（UTC），须已有账单
115		Amount int64  `json:"amount_fen"` // 正整数分
116	}
117	
118	// payment 是一笔实收登记：同一客户的一笔汇款（总额 Total 分）按分配列表
119	// 计入一个或多个已结算月份；单账单收款视为只有一项分配的汇款。
120	// 记录一旦写入永不删除；撤销只是追加撤销信息，整笔撤销全部分配并保留
121	// 原记录，撤销后该笔不再计入实收，也不会因重放而恢复。
122	type payment struct {
123		ID          string              `json:"id"`
124		CustomerID  string              `json:"customer_id"`
125		Total       int64               `json:"total_fen"` // 收款总额，正整数分，等于分配合计
126		Note        string              `json:"note"`
127		Allocations []paymentAllocation `json:"allocations"` // 至少一项，月份不重复，按月份升序保存
128		// Auto 为 true 表示该收款由 bill remit-auto 自动分配登记：首次分配由工具
129		// 按最早欠款账期确定，判重只看客户、总额与备注；false（含旧存档缺字段）
130		// 表示 bill pay / bill remit 的显式分配登记，仍按月份-金额对应关系判重。
131		// 自动与显式分配登记之间不得复用同一收款标识。
132		Auto         bool   `json:"auto,omitempty"`
133		Seq          int64  `json:"seq"` // 全局递增操作序号，决定历史展示顺序
134		CreatedAt    string `json:"created_at"`
135		Revoked      bool   `json:"revoked"`
136		RevokeReason string `json:"revoke_reason,omitempty"`
137		RevokeSeq    int64  `json:"revoke_seq,omitempty"`
138		RevokedAt    string `json:"revoked_at,omitempty"`
139	}
140	
141	// UnmarshalJSON 兼容旧版单账单收款格式（month + amount_fen，无 allocations）：
142	// 读入时归一化为一项分配，之后一律按新格式写回。
143	func (p *payment) UnmarshalJSON(data []byte) error {
144		type plain payment // 去掉方法，避免递归
145		var raw struct {
146			plain
147			Month  string `json:"month"`      // 旧格式：所属账单月份
148			Amount int64  `json:"amount_fen"` // 旧格式：收款金额
149		}
150		if err := json.Unmarshal(data, &raw); err != nil {
151			return err
152		}
153		*p = payment(raw.plain)
154		if len(p.Allocations) == 0 && raw.Month != "" {
155			p.Allocations = []paymentAllocation{{Month: raw.Month, Amount: raw.Amount}}
156			p.Total = raw.Amount
157		}
158		return nil
159	}
160	
161	// amountFor 返回该收款在指定月份的分配金额；无分配时为 0。
162	func (p *payment) amountFor(month string) int64 {
163		for _, al := range p.Allocations {
164			if al.Month == month {
165				return al.Amount
166			}
167		}
168		return 0
169	}
170	
171	// correction 是对一笔未撤销收款的分配更正：客户、总额、备注、原账单及
172	// 应付不变，仅把该笔收款当前生效的分配整体替换为完整新分配。记录一旦写入
173	// 永不删除；首次登记内容永久保留，bill pay / bill remit 仍按原始分配判重，
174	// 更正不影响收款身份。可连续更正，每次以当时最新分配为起点。
175	type correction struct {
176		ID          string              `json:"id"`
177		PaymentID   string              `json:"payment_id"` // 目标收款标识
178		Reason      string              `json:"reason"`
179		Allocations []paymentAllocation `json:"allocations"` // 完整新分配，至少一项，月份不重复，按月份升序保存
180		Seq         int64               `json:"seq"`         // 全局递增操作序号，与调整/收款及其撤销共用
181		CreatedAt   string              `json:"created_at"`
182	}
183	
184	// refund 是对一笔已登记收款的部分退款登记：从该收款当前最新分配涉及的
185	// 月份中实际退回资金，各月退款金额为正整数分，累计不得超过该笔在该月的
186	// 分配。记录一旦写入永不删除、不可撤销；首次退款后该收款的最新分配固定，
187	// 不得再新增分配更正或整笔撤销。退款标识与收款、调整、更正标识命名空间
188	// 相互独立，可同名。
189	type refund struct {
190		ID          string              `json:"id"`
191		PaymentID   string              `json:"payment_id"` // 目标收款标识
192		Reason      string              `json:"reason"`
193		Allocations []paymentAllocation `json:"allocations"` // 各月退款金额，至少一项，月份不重复，按月份升序保存
194		Seq         int64               `json:"seq"`         // 全局递增操作序号，与调整/收款/更正及其撤销共用
195		CreatedAt   string              `json:"created_at"`
196	}
197	
198	// planChange 是阶梯客户的一次按月生效的方案变更：自生效月（UTC 自然月，
199	// 含）起改用目标方案，直到下一次变更；生效月之前的月份不受影响。记录一旦
200	// 写入永不修改或删除；变更不产生账后流水事件，也不占用全局操作序号。
201	// 变更可被 plan revoke 撤销：撤销只追加撤销记录（PlanChangeRevocations），
202	// 原变更内容与原原因永久保留；有效方案只考虑未撤销变更，已撤销变更的月份
203	// 槽位仍永久占用（新变更不得复用该客户月份）。
204	type planChange struct {
205		CustomerID string `json:"customer_id"`
206		Month      string `json:"month"`   // YYYY-MM（UTC），生效月（含）
207		PlanID     string `json:"plan_id"` // 目标阶梯计费方案标识
208		Reason     string `json:"reason"`
209		CreatedAt  string `json:"created_at"`
210	}
211	
212	// planChangeRevocation 是一项方案变更的撤销登记：以客户与目标变更生效月
213	// 共同识别目标变更。原变更内容（目标方案与原因）永久保留，撤销只追加本
214	// 记录；撤销记录永久保留、不可撤销，每项变更只能撤销一次。撤销不产生账后
215	// 流水事件，也不占用全局操作序号。撤销后目标变更不再参与有效方案安排：
216	// 自其生效月起沿用此前最后一项未撤销变更的方案，无则用初始方案。
217	type planChangeRevocation struct {
218		CustomerID string `json:"customer_id"`
219		Month      string `json:"month"`  // 目标变更的生效月（YYYY-MM，UTC），与客户共同标识撤销目标
220		Reason     string `json:"reason"` // 撤销原因，非空
221		CreatedAt  string `json:"created_at"`
222	}
223	
224	// suspension 是阶梯客户的一段按月暂停区间：自起月（UTC 自然月，含）起
225	// 暂停服务，直到结束月（不含），即 [StartMonth, EndMonth) 覆盖的自然月。
226	// 暂停月不接收用量、不产生月费账单；区间可相接（相接视为连续暂停）但不得
227	// 重叠。记录一旦写入永不修改或删除；暂停不产生账后流水事件，也不占用全局
228	// 操作序号。固定单价客户不适用暂停。
229	type suspension struct {
230		CustomerID string `json:"customer_id"`
231		StartMonth string `json:"start_month"` // YYYY-MM（UTC），暂停起月（含）
232		EndMonth   string `json:"end_month"`   // YYYY-MM（UTC），原结束月（不含），严格晚于起月；登记提前恢复后仍永久保留原值
233		Reason     string `json:"reason"`      // 原暂停原因，永久保留
234		CreatedAt  string `json:"created_at"`
235	}
236	
237	// suspensionResume 是一段暂停的按月提前恢复登记：目标暂停由客户与原起月
238	// 共同标识，恢复月（UTC 自然月，含）起重新提供服务，该月不再受该项暂停
239	// 限制；目标暂停的当前有效区间由 [原起月, 原结束月) 缩短为 [原起月, 恢复月)，
240	// 原区间与原原因永久保留。恢复记录一旦写入永不修改、不可撤销，每项暂停只能
241	// 登记一次提前恢复；恢复不产生账后流水事件，也不占用全局操作序号。
242	type suspensionResume struct {
243		CustomerID  string `json:"customer_id"`
244		StartMonth  string `json:"start_month"`  // 目标暂停的原起月（YYYY-MM，UTC），与客户共同标识目标暂停
245		ResumeMonth string `json:"resume_month"` // YYYY-MM（UTC），恢复月（含）；严格满足 原起月 < 恢复月 < 原结束月
246		Reason      string `json:"reason"`       // 恢复原因，非空
247		CreatedAt   string `json:"created_at"`
248	}
249	
250	// withdrawal 是一条用量记录的撤回标记：原记录（客户、时间、数量、标识）永久
251	// 保留在 Usage 中，撤回只追加状态与原因，用于纠正误导入的记录。撤回不可恢复、
252	// 标识不可复用；已撤回用量不参与结算、方案变更预检与暂停区间冲突检查，但相同
253	// 内容的重放仍按原记录判重跳过。撤回只作用于该条记录，不占用全局操作序号。
254	type withdrawal struct {
255		UsageID   string `json:"usage_id"` // 撤回的用量标识（与键一致）
256		Reason    string `json:"reason"`   // 撤回原因，非空
257		CreatedAt string `json:"created_at"`
258	}
259	
260	// usageCorrection 是一条未封账用量的原子更正：以原用量标识为键，把错误的
261	// 客户、时间或数量替换为一条全新替代记录。更正成功时原记录按更正原因登记
262	// 撤回（Withdrawals 中保存同因撤回标记），替代记录登记到 Usage 并在此永久
263	// 保存关联；原内容不可改写，更正不可撤销，不占用账后操作序号。每条原用量
264	// 只能更正一次；替代记录本身仍可继续更正（形成前身→后继链）或按原规则撤回。
265	// 字段保存首次更正请求的完整内容，用于相同请求的幂等重放判定（时间按解析后
266	// 的瞬间比较）。
267	type usageCorrection struct {
268		UsageID       string `json:"usage_id"`       // 原用量标识（与键一致）
269		ReplacementID string `json:"replacement_id"` // 替代用量标识（全局唯一，首次更正时全新）
270		NewCustomerID string `json:"new_customer_id"`
271		NewTime       string `json:"new_time"` // RFC3339，保留首次更正的原始输入
272		NewQuantity   int64  `json:"new_quantity"`
273		Reason        string `json:"reason"` // 更正原因，同时是原记录的撤回原因，非空
274		CreatedAt     string `json:"created_at"`
275	}
276	
277	type state struct {
278		Version     int                     `json:"version"`
279		Customers   map[string]*customer    `json:"customers"`
280		Plans       map[string]*plan        `json:"plans"`             // 全局唯一方案标识 -> 阶梯计费方案
281		Usage       map[string]*usageRecord `json:"usage"`             // 全局唯一用量标识 -> 记录
282		Bills       map[string]*bill        `json:"bills"`             // 客户 + "|" + 月份 -> 账单
283		Adjustments map[string]*adjustment  `json:"adjustments"`       // 全局唯一调整标识 -> 记录
284		Payments    map[string]*payment     `json:"payments"`          // 全局唯一收款标识 -> 记录（与调整标识相互独立，可同名）
285		Corrections map[string]*correction  `json:"corrections"`       // 全局唯一更正标识 -> 记录（与收款、调整标识相互独立，可同名）
286		Refunds     map[string]*refund      `json:"refunds,omitempty"` // 全局唯一退款标识 -> 记录（与收款、调整、更正标识相互独立，可同名；不可撤销）
287		PlanChanges map[string]*planChange  `json:"plan_changes"`      // 客户 + "|" + 生效月 -> 方案变更（按生效月递增追加，不可改写；撤销后原记录仍保留）
288		// PlanChangeRevocations 以客户与目标变更生效月为键保存方案变更撤销登记；
289		// 原变更仍保留在 PlanChanges 中并永久可追溯，有效方案只考虑未撤销变更。
290		// 旧存档缺少本字段时全部变更视为有效。撤销记录永久保留、不可撤销。
291		PlanChangeRevocations map[string]*planChangeRevocation `json:"plan_change_revocations,omitempty"`
292		Suspensions           map[string]*suspension           `json:"suspensions,omitempty"` // 客户 + "|" + 起月 -> 暂停区间（原区间与原因不可改写）
293		// SuspensionResumes 以客户与原起月为键保存暂停的提前恢复登记；旧存档
294		// 缺少本字段时暂停沿用原区间。恢复记录永久保留、不可改写或撤销。
295		SuspensionResumes map[string]*suspensionResume `json:"suspension_resumes,omitempty"`
296		Withdrawals       map[string]*withdrawal       `json:"withdrawals,omitempty"` // 用量标识 -> 撤回标记（不可恢复，标识不可复用）
297		// UsageCorrections 以原用量标识为键保存用量更正关联；原记录同时在
298		// Withdrawals 中按更正原因标记撤回。旧存档缺少本字段视为无更正。
299		UsageCorrections map[string]*usageCorrection `json:"usage_corrections,omitempty"`
300		NextSeq          int64                       `json:"next_seq"` // 已分配的最大操作序号（调整/收款/更正/退款及其撤销共用；方案变更、暂停、用量撤回与用量更正不占用）
301		path             string                      `json:"-"`
302	}
303	
304	// loadStore 读取数据目录；目录不存在时按需创建并视为空库。
305	// 已存在但损坏或不可读取的数据一律报错，绝不当作空库覆盖。
306	func loadStore(dir string) (*state, error) {
307		p := filepath.Join(dir, "state.json")
308		data, err := os.ReadFile(p)
309		if err != nil {
310			if errors.Is(err, os.ErrNotExist) {
311				if mkErr := os.MkdirAll(dir, 0o755); mkErr != nil {
312					return nil, fmt.Errorf("无法创建数据目录 %s: %w", dir, mkErr)
313				}
314				return newState(p), nil
315			}
316			return nil, fmt.Errorf("数据文件不可读取 %s: %w", p, err)
317		}
318	
319		var s state
320		dec := json.NewDecoder(bytes.NewReader(data))
321		if err := dec.Decode(&s); err != nil {
322			return nil, fmt.Errorf("数据文件已损坏（不是有效的 JSON）%s: %w", p, err)
323		}
324		// 拒绝完整 JSON 之后的任何非空白内容（包括单独的 ] 或 }），避免静默
325		// 吞掉异常数据；合法尾随空白仍可读取。
326		if off := dec.InputOffset(); off < int64(len(data)) {
327			if strings.TrimSpace(string(data[off:])) != "" {
328				return nil, fmt.Errorf("数据文件已损坏（JSON 之后存在多余内容）: %s", p)
329			}
330		}
331		if err := s.validate(); err != nil {
332			return nil, fmt.Errorf("数据文件已损坏: %w", err)
333		}
334		// 旧版本数据文件没有 plans/adjustments/payments/corrections/refunds/
335		// plan_changes/suspensions/withdrawals/usage_corrections/next_seq 字段：
336		// 视为零方案、零调整、零实收、零更正、零退款、零方案变更、零暂停、
337		// 零撤回、零用量更正（全部用量有效）。
338		if s.Plans == nil {
339			s.Plans = map[string]*plan{}
340		}
341		if s.Adjustments == nil {
342			s.Adjustments = map[string]*adjustment{}
343		}
344		if s.Payments == nil {
345			s.Payments = map[string]*payment{}
346		}
347		if s.Corrections == nil {
348			s.Corrections = map[string]*correction{}
349		}
350		if s.Refunds == nil {
351			s.Refunds = map[string]*refund{}
352		}
353		if s.PlanChanges == nil {
354			s.PlanChanges = map[string]*planChange{}
355		}
356		if s.PlanChangeRevocations == nil {
357			s.PlanChangeRevocations = map[string]*planChangeRevocation{}
358		}
359		if s.Suspensions == nil {
360			s.Suspensions = map[string]*suspension{}
361		}
362		if s.SuspensionResumes == nil {
363			s.SuspensionResumes = map[string]*suspensionResume{}
364		}
365		if s.Withdrawals == nil {
366			s.Withdrawals = map[string]*withdrawal{}
367		}
368		if s.UsageCorrections == nil {
369			s.UsageCorrections = map[string]*usageCorrection{}
370		}
371		s.path = p
372		return &s, nil
373	}
374	
375	func newState(p string) *state {
376		return &state{
377			Version:               stateVersion,
378			Customers:             map[string]*customer{},
379			Plans:                 map[string]*plan{},
380			Usage:                 map[string]*usageRecord{},
381			Bills:                 map[string]*bill{},
382			Adjustments:           map[string]*adjustment{},
383			Payments:              map[string]*payment{},
384			Corrections:           map[string]*correction{},
385			Refunds:               map[string]*refund{},
386			PlanChanges:           map[string]*planChange{},
387			PlanChangeRevocations: map[string]*planChangeRevocation{},
388			Suspensions:           map[string]*suspension{},
389			SuspensionResumes:     map[string]*suspensionResume{},
390			Withdrawals:           map[string]*withdrawal{},
391			UsageCorrections:      map[string]*usageCorrection{},
392			path:                  p,
393		}
394	}
395	
396	// validate 对读入的库做一致性检查，任何异常都按损坏处理。
397	func (s *state) validate() error {
398		if s.Version != stateVersion {
399			return fmt.Errorf("不支持的数据版本 %d（仅支持 %d）", s.Version, stateVersion)
400		}
401		if s.Customers == nil || s.Usage == nil || s.Bills == nil {
402			return errors.New("缺少必要的数据节")
403		}
404		for id, p := range s.Plans {
405			if p == nil {
406				return fmt.Errorf("方案 %q 的数据为空", id)
407			}
408			if p.ID != id {
409				return fmt.Errorf("方案标识不一致: 键 %q / 记录 %q", id, p.ID)
410			}
411			if err := validatePlanRules(p); err != nil {
412				return err
413			}
414		}
415		for id, c := range s.Customers {
416			if c == nil {
417				return fmt.Errorf("客户 %q 的数据为空", id)
418			}
419			if c.ID != id {
420				return fmt.Errorf("客户标识不一致: 键 %q / 记录 %q", id, c.ID)
421			}
422			if c.ID == "" || c.Name == "" {
423				return fmt.Errorf("客户 %q 的标识或名称为空", id)
424			}
425			if c.Price < 0 {
426				return fmt.Errorf("客户 %q 单价为负", id)
427			}
428			if c.PlanID != "" {
429				if _, ok := s.Plans[c.PlanID]; !ok {
430					return fmt.Errorf("客户 %q 绑定了不存在的方案 %q", id, c.PlanID)
431				}
432			}
433		}
434		// 方案变更：键、客户（须为绑定阶梯方案的客户）、目标方案、生效月与
435		// 原因都必须自洽；同一客户的变更生效月由键保证唯一。
436		for key, ch := range s.PlanChanges {
437			if ch == nil {
438				return fmt.Errorf("方案变更 %q 的数据为空", key)
439			}
440			if planChangeKey(ch.CustomerID, ch.Month) != key {
441				return fmt.Errorf("方案变更键不一致: 键 %q / 客户月份 %s|%s", key, ch.CustomerID, ch.Month)
442			}
443			c, ok := s.Customers[ch.CustomerID]
444			if !ok {
445				return fmt.Errorf("方案变更 %q 引用了不存在的客户 %q", key, ch.CustomerID)
446			}
447			if c.PlanID == "" {
448				return fmt.Errorf("方案变更 %q 的客户 %q 未绑定阶梯方案", key, ch.CustomerID)
449			}
450			if !validMonth(ch.Month) {
451				return fmt.Errorf("方案变更 %q 的生效月无效", key)
452			}
453			if _, ok := s.Plans[ch.PlanID]; !ok {
454				return fmt.Errorf("方案变更 %q 引用了不存在的方案 %q", key, ch.PlanID)
455			}
456			if strings.TrimSpace(ch.Reason) == "" {
457				return fmt.Errorf("方案变更 %q 的原因为空", key)
458			}
459		}
460		// 方案变更撤销登记：键与客户/目标生效月一致；引用的目标变更必须存在
461		// （失效撤销引用即损坏）；撤销原因非空。原变更内容、原原因与撤销记录都
462		// 永久保留，撤销不可撤销。旧文件缺少撤销记录时全部变更视为有效
463		// （PlanChangeRevocations 已在载入时补为空表）。账单方案与撤销后有效
464		// 安排的一致性由阶梯账单校验（validateTieredBill）把关。
465		for key, rv := range s.PlanChangeRevocations {
466			if rv == nil {
467				return fmt.Errorf("方案变更撤销 %q 的数据为空", key)
468			}
469			if planChangeKey(rv.CustomerID, rv.Month) != key {
470				return fmt.Errorf("方案变更撤销键不一致: 键 %q / 客户月份 %s|%s", key, rv.CustomerID, rv.Month)
471			}
472			if _, ok := s.PlanChanges[key]; !ok {
473				return fmt.Errorf("方案变更撤销 %q 引用了不存在的方案变更（客户 %q 生效月 %q，撤销目标失效）",
474					key, rv.CustomerID, rv.Month)
475			}
476			if !validMonth(rv.Month) {
477				return fmt.Errorf("方案变更撤销 %q 的目标生效月无效", key)
478			}
479			if strings.TrimSpace(rv.Reason) == "" {
480				return fmt.Errorf("方案变更撤销 %q 的原因为空", key)
481			}
482		}
483		for id, u := range s.Usage {
484			if u == nil {
485				return fmt.Errorf("用量 %q 的数据为空", id)
486			}
487			if u.ID != id {
488				return fmt.Errorf("用量标识不一致: 键 %q / 记录 %q", id, u.ID)
489			}
490			if u.ID == "" {
491				return errors.New("存在空的用量标识")
492			}
493			if _, ok := s.Customers[u.CustomerID]; !ok {
494				return fmt.Errorf("用量 %q 引用了不存在的客户 %q", u.ID, u.CustomerID)
495			}
496			if u.Quantity <= 0 {
497				return fmt.Errorf("用量 %q 的数量非正", u.ID)
498			}
499			if _, err := time.Parse(time.RFC3339, u.Time); err != nil {
500				return fmt.Errorf("用量 %q 的时间不是 RFC3339: %w", u.ID, err)
501			}
502		}
503		// 撤回标记：键与记录一致、目标用量存在（撤回目标失效即损坏）、原因非空。
504		// 原用量记录仍按上面的规则完整校验（格式、正数量、客户存在性），撤回不
505		// 删除或改写原记录。旧文件缺少撤回记录视为全部用量有效（Withdrawals 已
506		// 在载入时补为空表）。
507		for id, w := range s.Withdrawals {
508			if w == nil {
509				return fmt.Errorf("用量 %q 的撤回记录为空", id)
510			}
511			if w.UsageID != id {
512				return fmt.Errorf("撤回记录键不一致: 键 %q / 用量标识 %q", id, w.UsageID)
513			}
514			if w.UsageID == "" {
515				return errors.New("存在空用量标识的撤回记录")
516			}
517			if _, ok := s.Usage[w.UsageID]; !ok {
518				return fmt.Errorf("撤回记录引用了不存在的用量 %q（撤回目标失效）", w.UsageID)
519			}
520			if strings.TrimSpace(w.Reason) == "" {
521				return fmt.Errorf("用量 %q 的撤回原因为空", w.UsageID)
522			}
523		}
524		// 用量更正关联：键与原标识一致；原记录与替代记录都必须存在于 Usage，
525		// 替代记录内容（客户、解析后的时间点、数量）须与更正保存的新内容一致；
526		// 原记录必须已按更正原因撤回（撤回标记的原因与更正原因不符即损坏）；
527		// 同一替代记录只能有一个来源；关联不得成环。替代记录后来被合法撤回或
528		// 继续更正（即它本身又作为某条更正的原记录）属正常状态，不判为损坏。
529		// 旧文件缺少更正记录视为无更正（UsageCorrections 已在载入时补为空表）。
530		replacementSources := make(map[string]string) // 替代用量标识 -> 原用量标识
531		for id, uc := range s.UsageCorrections {
532			if uc == nil {
533				return fmt.Errorf("用量更正 %q 的数据为空", id)
534			}
535			if uc.UsageID != id {
536				return fmt.Errorf("用量更正键不一致: 键 %q / 原用量标识 %q", id, uc.UsageID)
537			}
538			if uc.UsageID == "" {
539				return errors.New("存在空原用量标识的更正记录")
540			}
541			if strings.TrimSpace(uc.Reason) == "" {
542				return fmt.Errorf("用量更正 %q 的原因为空", id)
543			}
544			orig, ok := s.Usage[uc.UsageID]
545			if !ok {
546				return fmt.Errorf("用量更正 %q 引用了不存在的原用量 %q（更正来源失效）", id, uc.UsageID)
547			}
548			// 原记录内容不可改写：原用量记录仍须是正常的正数量有效格式（已在
549			// 上面的用量校验中核验），此处仅确认其存在。
550			if orig.ID != uc.UsageID {
551				return fmt.Errorf("用量更正 %q 的原记录标识不一致", id)
552			}
553			if uc.ReplacementID == "" {
554				return fmt.Errorf("用量更正 %q 缺少替代用量标识", id)
555			}
556			if uc.ReplacementID == uc.UsageID {
557				return fmt.Errorf("用量更正 %q 的替代标识与原标识相同", id)
558			}
559			repl, ok := s.Usage[uc.ReplacementID]
560			if !ok {
561				return fmt.Errorf("用量更正 %q 引用了不存在的替代用量 %q（更正目标失效）", id, uc.ReplacementID)
562			}
563			if src, dup := replacementSources[uc.ReplacementID]; dup {
564				return fmt.Errorf("替代用量 %q 同时是用量 %q 与 %q 的更正替代（同一替代记录不得有多个来源）",
565					uc.ReplacementID, src, uc.UsageID)
566			}
567			replacementSources[uc.ReplacementID] = uc.UsageID
568			if _, ok := s.Customers[uc.NewCustomerID]; !ok {
569				return fmt.Errorf("用量更正 %q 引用了不存在的新客户 %q", id, uc.NewCustomerID)
570			}
571			nt, err := time.Parse(time.RFC3339, uc.NewTime)
572			if err != nil {
573				return fmt.Errorf("用量更正 %q 的新时间不是 RFC3339: %w", id, err)
574			}
575			if uc.NewQuantity <= 0 {
576				return fmt.Errorf("用量更正 %q 的新数量非正", id)
577			}
578			rt, err := time.Parse(time.RFC3339, repl.Time)
579			if err != nil {
580				return fmt.Errorf("用量更正 %q 的替代记录 %q 时间不是 RFC3339: %w", id, uc.ReplacementID, err)
581			}
582			// 替代记录内容（客户、解析后的时间点、数量）必须与更正保存的新内容一致；
583			// 时间按瞬间比较，Z 与 +08:00 表示同一时刻视为一致。
584			if repl.CustomerID != uc.NewCustomerID || repl.Quantity != uc.NewQuantity || !rt.Equal(nt) {
585				return fmt.Errorf("用量更正 %q 的替代记录 %q 内容与保存的新内容不一致（更正关联损坏）",
586					id, uc.ReplacementID)
587			}
588			// 原记录必须已撤回，且撤回原因就是更正原因。
589			w, ok := s.Withdrawals[uc.UsageID]
590			if !ok {
591				return fmt.Errorf("用量更正 %q 的原用量 %q 未撤回（更正须把原记录按更正原因标记撤回）", id, uc.UsageID)
592			}
593			if w.Reason != uc.Reason {
594				return fmt.Errorf("用量更正 %q 的原用量 %q 撤回原因 %q 与更正原因 %q 不符",
595					id, uc.UsageID, w.Reason, uc.Reason)
596			}
597		}
598		// 关联成环检测：沿“原记录 -> 替代记录”的更正链前进，重复访问即成环。
599		// 合法链必然终止于一条未再被更正的记录。
600		for id := range s.UsageCorrections {
601			seen := map[string]bool{id: true}
602			cur := id
603			for {
604				uc, ok := s.UsageCorrections[cur]
605				if !ok {
606					break // 链终止于未再被更正的记录
607				}
608				if seen[uc.ReplacementID] {
609					return fmt.Errorf("用量更正关联在 %q 处成环（更正链不得成环）", uc.ReplacementID)
610				}
611				seen[uc.ReplacementID] = true
612				cur = uc.ReplacementID
613			}
614		}
615		for key, b := range s.Bills {
616			if b == nil {
617				return fmt.Errorf("账单 %q 的数据为空", key)
618			}
619			if billKey(b.CustomerID, b.Month) != key {
620				return fmt.Errorf("账单键不一致: 键 %q / 客户月份 %s|%s", key, b.CustomerID, b.Month)
621			}
622			if _, ok := s.Customers[b.CustomerID]; !ok {
623				return fmt.Errorf("账单 %q 引用了不存在的客户 %q", key, b.CustomerID)
624			}
625			if !validMonth(b.Month) {
626				return fmt.Errorf("账单 %q 的月份无效", key)
627			}
628			if b.MonthlyFee < 0 {
629				return fmt.Errorf("账单 %q 的月费为负", key)
630			}
631			// 仅月费大于 0 的账单允许空用量明细（无用量也须出账收取月费）。
632			if len(b.Lines) == 0 && b.MonthlyFee == 0 {
633				return fmt.Errorf("账单 %q 没有明细", key)
634			}
635			var qty, fee int64
636			for _, ln := range b.Lines {
637				u, ok := s.Usage[ln.UsageID]
638				if !ok {
639					return fmt.Errorf("账单 %q 引用了不存在的用量 %q", key, ln.UsageID)
640				}
641				// 已撤回用量不参与结算，账单不得把已撤回记录视为待计费用量。
642				if _, withdrawn := s.Withdrawals[ln.UsageID]; withdrawn {
643					return fmt.Errorf("账单 %q 引用了已撤回的用量 %q", key, ln.UsageID)
644				}
645				if u.CustomerID != b.CustomerID || u.Time != ln.Time || u.Quantity != ln.Quantity {
646					return fmt.Errorf("账单 %q 的明细 %q 与用量记录不一致", key, ln.UsageID)
647				}
648				if !inMonth(u.Time, b.Month) {
649					return fmt.Errorf("账单 %q 的明细 %q 不在账期内", key, ln.UsageID)
650				}
651				var err error
652				qty, err = add64(qty, ln.Quantity)
653				if err != nil {
654					return fmt.Errorf("账单 %q 汇总数量溢出", key)
655				}
656				fee, err = add64(fee, ln.LineFee)
657				if err != nil {
658					return fmt.Errorf("账单 %q 汇总金额溢出", key)
659				}
660			}
661			if qty != b.TotalQty {
662				return fmt.Errorf("账单 %q 总数量与明细不符", key)
663			}
664			// 原总金额 = 月费 + 全月用量费；月费不计入逐条用量小计，故明细
665			// 小计之和等于用量费（总金额 − 月费）。月费与总金额均非负，相减
666			// 不会溢出；总金额为负或小于月费时此处必然不符。
667			if usageFee := b.TotalFee - b.MonthlyFee; fee != usageFee {
668				return fmt.Errorf("账单 %q 总金额不等于月费加全月用量费（明细小计合计 %d 分，月费 %d 分，总金额 %d 分）",
669					key, fee, b.MonthlyFee, b.TotalFee)
670			}
671			c := s.Customers[b.CustomerID]
672			switch b.Pricing {
673			case "", "fixed":
674				// 固定单价账单：每条小计必须等于 数量×客户固定单价，且不得
675				// 携带阶梯方案信息、分段或月费。
676				if b.PlanID != "" || b.PlanName != "" || len(b.PlanTiers) > 0 || len(b.TierTotals) > 0 {
677					return fmt.Errorf("账单 %q 是固定单价账单但携带阶梯方案信息", key)
678				}
679				if b.MonthlyFee != 0 {
680					return fmt.Errorf("账单 %q 是固定单价账单但携带月费", key)
681				}
682				for _, ln := range b.Lines {
683					if len(ln.Segments) > 0 {
684						return fmt.Errorf("账单 %q 的明细 %q 携带阶梯分段", key, ln.UsageID)
685					}
686					lf, err := mul64(ln.Quantity, c.Price)
687					if err != nil {
688						return fmt.Errorf("账单 %q 明细 %q 小计溢出", key, ln.UsageID)
689					}
690					if lf != ln.LineFee {
691						return fmt.Errorf("账单 %q 明细 %q 小计与数量×单价不符", key, ln.UsageID)
692					}
693				}
694				if b.UnitPrice != c.Price {
695					return fmt.Errorf("账单 %q 单价与客户固定单价不符", key)
696				}
697			case "tiered":
698				if err := s.validateTieredBill(key, b, c); err != nil {
699					return err
700				}
701			default:
702				return fmt.Errorf("账单 %q 的计价类型 %q 未知", key, b.Pricing)
703			}
704			// 封账期内不得存在游离于账单之外的有效用量（封账后新增被禁止，
705			// 而已入账记录理应全部在明细中）；已撤回用量不计费用，允许存在
706			// 于已封账月份而不进入账单。
707			for _, u := range s.Usage {
708				if _, withdrawn := s.Withdrawals[u.ID]; withdrawn {
709					continue
710				}
711				if u.CustomerID == b.CustomerID && inMonth(u.Time, b.Month) {
712					found := false
713					for _, ln := range b.Lines {
714						if ln.UsageID == u.ID {
715							found = true
716							break
717						}
718					}
719					if !found {
