1092				return fmt.Errorf("账单 %q 的收款金额与记录不一致: %w", key, err)
1093			}
1094			if received > payable {
1095				return fmt.Errorf("账单 %q 的实收 %d 分超过当前应付 %d 分", key, received, payable)
1096			}
1097		}
1098		return nil
1099	}
