1101	// validatePlanRules 校验阶梯方案的标识、名称、月费与阶梯规则本身自洽：
1102	// 月费为非负整数分，至少一档，有限上限为严格递增的正整数，最后一档无
1103	// 上限，单价非负。
1104	func validatePlanRules(p *plan) error {
1105		if p.ID == "" || p.Name == "" {
1106			return fmt.Errorf("方案 %q 的标识或名称为空", p.ID)
1107		}
1108		if p.MonthlyFee < 0 {
1109			return fmt.Errorf("方案 %q 的月费为负", p.ID)
1110		}
1111		if len(p.Tiers) == 0 {
1112			return fmt.Errorf("方案 %q 至少需要一档阶梯", p.ID)
1113		}
1114		prev := int64(0)
1115		for i, t := range p.Tiers {
1116			if t.Price < 0 {
1117				return fmt.Errorf("方案 %q 第 %d 档单价为负", p.ID, i+1)
1118			}
1119			if i == len(p.Tiers)-1 {
1120				if t.Limit != 0 {
1121					return fmt.Errorf("方案 %q 最后一档必须无上限", p.ID)
1122				}
1123			} else {
1124				if t.Limit <= 0 {
1125					return fmt.Errorf("方案 %q 第 %d 档上限必须是正整数", p.ID, i+1)
1126				}
1127				if t.Limit <= prev {
1128					return fmt.Errorf("方案 %q 的有限上限必须严格递增", p.ID)
1129				}
1130				prev = t.Limit
1131			}
1132		}
1133		return nil
1134	}
