1162	// sortedByInstant 判定用量记录是否按（解析后的时间点升序、同一时间按
1163	// 标识字典序）排列，即阶梯计价的计价顺序。
1164	func sortedByInstant(recs []*usageRecord) bool {
1165		for i := 1; i < len(recs); i++ {
1166			ti, _ := time.Parse(time.RFC3339, recs[i-1].Time)
1167			tj, _ := time.Parse(time.RFC3339, recs[i].Time)
1168			ui, uj := ti.UTC(), tj.UTC()
1169			if uj.Before(ui) || (uj.Equal(ui) && recs[i].ID <= recs[i-1].ID) {
1170				return false
1171			}
1172		}
1173		return true
1174	}
