1176	// validateTieredBill 校验阶梯账单：方案引用有效、快照与方案一致、账单方案
1177	// 符合账期月的方案安排，并按保存的方案规则从零累计重放计价，逐条比对分段、
1178	// 小计、各档合计与总金额；任何不符都视为数据损坏。
1179	func (s *state) validateTieredBill(key string, b *bill, c *customer) error {
1180		if b.PlanID == "" {
1181			return fmt.Errorf("账单 %q 缺少方案标识", key)
1182		}
1183		p, ok := s.Plans[b.PlanID]
1184		if !ok {
1185			return fmt.Errorf("账单 %q 引用了不存在的方案 %q", key, b.PlanID)
1186		}
1187		if b.PlanName != p.Name {
1188			return fmt.Errorf("账单 %q 的方案名称快照与方案 %q 不符", key, b.PlanID)
1189		}
1190		if !tiersEqual(b.PlanTiers, p.Tiers) {
1191			return fmt.Errorf("账单 %q 的方案规则快照与方案 %q 不符", key, b.PlanID)
1192		}
1193		if b.MonthlyFee != p.MonthlyFee {
1194			return fmt.Errorf("账单 %q 的月费快照与方案 %q 不符", key, b.PlanID)
1195		}
1196		// 账单方案必须符合账期安排：创建时绑定的初始方案被生效月不晚于
1197		// 账期月的最后一次变更替换（无变更时即初始绑定，兼容旧存档）。
1198		if want := s.effectivePlanID(c, b.Month); want != b.PlanID {
1199			return fmt.Errorf("账单 %q 的方案 %q 与账期 %s 安排的方案 %q 不一致", key, b.PlanID, b.Month, want)
1200		}
1201		if b.UnitPrice != 0 {
1202			return fmt.Errorf("账单 %q 是阶梯账单但保存了统一单价", key)
1203		}
1204		if len(b.TierTotals) != len(p.Tiers) {
1205			return fmt.Errorf("账单 %q 的分档合计档数与方案规则不符", key)
1206		}
1207		// 明细必须按计价顺序排列（前面已逐条核验与用量记录一致）。
1208		recs := make([]*usageRecord, len(b.Lines))
1209		for i, ln := range b.Lines {
1210			recs[i] = s.Usage[ln.UsageID]
1211		}
1212		if !sortedByInstant(recs) {
1213			return fmt.Errorf("账单 %q 的明细未按计价顺序（时间点升序、同一时间按标识字典序）排列", key)
1214		}
1215		priced, err := tieredPrice(p.Tiers, recs)
1216		if err != nil {
1217			return fmt.Errorf("账单 %q 按方案规则计价失败: %w", key, err)
1218		}
1219		for i, ln := range b.Lines {
1220			if !segmentsEqual(ln.Segments, priced.lines[i].segments) {
1221				return fmt.Errorf("账单 %q 的明细 %q 分段与计价规则不符", key, ln.UsageID)
1222			}
1223			if ln.LineFee != priced.lines[i].fee {
1224				return fmt.Errorf("账单 %q 的明细 %q 小计与计价规则不符", key, ln.UsageID)
1225			}
1226		}
1227		for i, tt := range b.TierTotals {
1228			if tt.Quantity != priced.tierQty[i] || tt.Fee != priced.tierFee[i] {
1229				return fmt.Errorf("账单 %q 的第 %d 档合计与计价规则不符", key, i+1)
1230			}
1231		}
1232		// 原总金额 = 月费 + 全月用量费；月费不进入分档合计与逐条小计。
1233		wantTotal, err := add64(priced.totalFee, b.MonthlyFee)
1234		if err != nil || wantTotal != b.TotalFee {
1235			return fmt.Errorf("账单 %q 总金额不等于月费加全月用量费", key)
1236		}
1237		return nil
1238	}
