1240	// save 整体原子落盘：先写临时文件并同步，再 rename 覆盖。
1241	// 只有完整保存成功后调用方才会向用户报告成功。
1242	func (s *state) save() error {
1243		if err := s.validate(); err != nil {
1244			return fmt.Errorf("拒绝写入不一致的数据: %w", err)
1245		}
1246		data, err := json.MarshalIndent(s, "", "  ")
1247		if err != nil {
1248			return fmt.Errorf("序列化数据失败: %w", err)
1249		}
1250		data = append(data, '\n')
1251	
1252		tmp := s.path + ".tmp"
1253		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
1254		if err != nil {
1255			return fmt.Errorf("写入临时数据文件失败: %w", err)
1256		}
1257		if _, err := f.Write(data); err != nil {
1258			f.Close()
1259			os.Remove(tmp)
1260			return fmt.Errorf("写入临时数据文件失败: %w", err)
1261		}
1262		if err := f.Sync(); err != nil {
1263			f.Close()
1264			os.Remove(tmp)
1265			return fmt.Errorf("同步数据文件失败: %w", err)
1266		}
1267		if err := f.Close(); err != nil {
1268			os.Remove(tmp)
1269			return fmt.Errorf("关闭数据文件失败: %w", err)
1270		}
1271		if err := os.Rename(tmp, s.path); err != nil {
1272			os.Remove(tmp)
1273			return fmt.Errorf("替换数据文件失败: %w", err)
1274		}
1275		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
1276			dir.Sync()
1277			dir.Close()
1278		}
1279		return nil
1280	}
