1381	// 则用初始方案，直到其后下一项未撤销变更的生效月前。
1382	func (s *state) effectivePlanID(cust *customer, month string) string {
1383		planID := cust.PlanID
1384		latest := ""
1385		for _, ch := range s.PlanChanges {
1386			if ch.CustomerID != cust.ID || s.planChangeRevoked(ch.CustomerID, ch.Month) {
1387				continue
1388			}
1389			if ch.Month <= month && ch.Month >= latest {
1390				latest = ch.Month
1391				planID = ch.PlanID
1392			}
1393		}
1394		return planID
1395	}
