1461	func paymentsEverFor(s *state, customerID, month string) []*payment {
1462		var list []*payment
1463		for _, p := range s.Payments {
1464			if p.CustomerID != customerID {
1465				continue
1466			}
1467			involved := p.amountFor(month) > 0
1468			if !involved {
1469				for _, c := range s.Corrections {
1470					if c.PaymentID == p.ID && allocAmountFor(c.Allocations, month) > 0 {
1471						involved = true
1472						break
1473					}
1474				}
1475			}
1476			if involved {
1477				list = append(list, p)
1478			}
1479		}
1480		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
