1484	// paymentReceived 返回全部未撤销收款按最新分配在指定月份计入并扣除退款后
1485	// 的实收之和。各笔净额（分配减累计退款）均为非负整数，用非负 64 位加法
1486	// 累加，溢出时返回错误。
1487	func paymentReceived(s *state, customerID, month string) (int64, error) {
1488		var received int64
1489		for _, p := range s.Payments {
1490			if p.CustomerID != customerID || p.Revoked {
1491				continue
1492			}
1493			amt := allocAmountFor(currentAllocations(s, p), month) - refundedForMonth(s, p.ID, month)
1494			if amt <= 0 {
1495				continue
1496			}
1497			var err error
1498			received, err = add64(received, amt)
1499			if err != nil {
1500				return 0, err
1501			}
1502		}
1503		return received, nil
1504	}
