1541	// errPayableOutOfRange 表示当前应付越出 [0, 有符号 64 位最大值]。
1542	var errPayableOutOfRange = errors.New("当前应付越界（须介于 0 与有符号 64 位最大值之间）")
1543	
1544	// billTotals 计算全部未撤销调整的净额与当前应付（原总金额 + 净额）。
1545	// 净额按 128 位精确求和（与顺序无关），再校验应付落在
1546	// [0, 有符号 64 位最大值] 内，全程整数运算。
1547	func billTotals(b *bill, adjs []*adjustment) (net, payable int64, err error) {
1548		var amounts []int64
1549		for _, a := range adjs {
1550			if !a.Revoked {
1551				amounts = append(amounts, a.Amount)
1552			}
1553		}
1554		net, err = sumSigned64(amounts...)
1555		if err != nil {
1556			return 0, 0, err
1557		}
1558		payable, err = addSigned64(b.TotalFee, net)
1559		if err != nil {
1560			return 0, 0, err
1561		}
1562		if payable < 0 {
1563			return 0, 0, errPayableOutOfRange
1564		}
1565		return net, payable, nil
1566	}
