266	func parsePrice(text string) (int64, error) {
267		text = strings.TrimSpace(text)
268		price, err := strconv.ParseInt(text, 10, 64)
269		if err != nil {
270			return 0, fmt.Errorf("单价 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
271		}
272		if price < 0 {
273			return 0, fmt.Errorf("单价必须是非负整数分，收到 %d", price)
274		}
