285	func cmdUsageImport(dir, file string) error {
286		var reader io.ReadCloser
287		var source string
288		if file == "-" {
289			reader = io.NopCloser(os.Stdin)
290			source = "标准输入"
291		} else {
292			f, err := os.Open(file)
293			if err != nil {
294				return fmt.Errorf("无法打开用量文件 %s: %w", file, err)
295			}
296			reader = f
297			source = file
298		}
299		defer reader.Close()
300	
301		rows, parseErrs := parseUsageFile(reader)
302	
303		s, err := loadStore(dir)
304		if err != nil {
305			return err
306		}
307	
308		// 先校验：任何问题都在此阶段收集，全部通过后才一次性修改并保存，
309		// 保证“整批导入先校验再生效”，失败不留下任何新用量。
310		var problems []string
311		problems = append(problems, parseErrs...)
312	
313		accepted := make(map[string]*parsedRow) // 本批内首次出现、内容确定的记录
314		var ordered []*parsedRow
315		newCount, dupCount := 0, 0
316	
317		for _, r := range rows {
318			cust, ok := s.Customers[r.rec.CustomerID]
319			if !ok {
320				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识 %q 不存在", r.line, r.rec.CustomerID))
321				continue
322			}
323	
324			// 去重判定同时对“库中已有”和“本文件内已出现”生效，且先于暂停、
325			// 封账与金额预检：已存在记录（含已撤回记录）按客户、解析后的时间点
326			// 和数量与原内容判重，相同重放计入重复跳过——即使该月后来已封账、
327			// 暂停或后续方案计价会溢出也不受阻；已撤回记录的重放不会恢复记录。
328			var existing *usageRecord
329			if inStore, ok := s.Usage[r.rec.ID]; ok {
330				existing = inStore
331			} else if inBatch, ok := accepted[r.rec.ID]; ok {
332				existing = &inBatch.rec
333			}
334			if existing != nil {
335				if !sameUsage(existing, &r.rec, r.t) {
336					problems = append(problems, fmt.Sprintf("第 %d 行：用量标识 %q 已存在但内容不同（已有客户=%s 时间=%s 数量=%d）",
337						r.line, r.rec.ID, existing.CustomerID, existing.Time, existing.Quantity))
338					continue
339				}
340				dupCount++
341				continue
342			}
343	
344			// 以下为全新用量：暂停、封账及当前方案下金额预检只约束全新用量。
345			// 暂停月的新用量一律拒绝：按记录时间换算的 UTC 月份判断，处于任一
346			// 暂停区间（含起月、不含结束月）即整批失败并指出行号。
347			rowMonth := r.t.UTC().Format("2006-01")
348			if s.isSuspendedMonth(r.rec.CustomerID, rowMonth) {
349				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 处于暂停区间，暂停服务期间不接收用量（新用量 %q 被拒绝）",
350					r.line, r.rec.CustomerID, rowMonth, r.rec.ID))
351				continue
352			}
353			// 金额可行性预检：固定单价客户检查 数量×单价；阶梯客户按记录时间
354			// 换算的 UTC 月份的有效方案，以单条数量从零计价，检查分段金额不
355			// 溢出（金额单位：分）。
356			if cust.PlanID == "" {
357				if _, err := mul64(r.rec.Quantity, cust.Price); err != nil {
358					problems = append(problems, fmt.Sprintf("第 %d 行：数量 %d × 单价 %d 金额溢出有符号 64 位整数范围", r.line, r.rec.Quantity, cust.Price))
359					continue
360				}
361			} else {
362				rec := r.rec
363				planID := s.effectivePlanID(cust, rowMonth)
364				if _, err := tieredPrice(s.Plans[planID].Tiers, []*usageRecord{&rec}); err != nil {
365					problems = append(problems, fmt.Sprintf("第 %d 行：按 %s 月有效方案 %q 对单条数量从零计价失败：%v", r.line, rowMonth, planID, err))
366					continue
367				}
368			}
369	
370			// 全新标识：不得进入该客户已封账的 UTC 自然月。
371			if s.sealed(r.rec.CustomerID, rowMonth) {
372				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 已封账，新用量 %q 不得进入",
373					r.line, r.rec.CustomerID, rowMonth, r.rec.ID))
374				continue
375			}
376	
377			rr := r
378			accepted[r.rec.ID] = rr
379			ordered = append(ordered, rr)
380			newCount++
381		}
382	
383		if len(problems) > 0 {
384			return fmt.Errorf("导入失败，整批未生效（共 %d 个问题）：\n  %s", len(problems), strings.Join(problems, "\n  "))
385		}
386	
387		for _, r := range ordered {
388			rec := r.rec
389			s.Usage[rec.ID] = &rec
390		}
391		if err := s.save(); err != nil {
392			return err
393		}
394		fmt.Fprintf(stdout, "导入完成（%s）：新增 %d 条，重复跳过 %d 条\n", source, newCount, dupCount)
395		return nil
396	}
