398	// parseUsageFile 完整读取 CSV，做格式层面的解析；业务层面的校验在调用方完成。
399	func parseUsageFile(r io.Reader) ([]*parsedRow, []string) {
400		cr := csv.NewReader(r)
401		cr.FieldsPerRecord = 4
402		cr.TrimLeadingSpace = true
403	
404		header, err := cr.Read()
405		if err == io.EOF {
406			return nil, []string{"文件为空：首行必须是表头 " + usageHeader}
407		}
408		if err != nil {
409			return nil, []string{fmt.Sprintf("无法读取表头：%v（首行必须是 %s）", err, usageHeader)}
410		}
411		for i := range header {
412			header[i] = strings.TrimSpace(header[i])
413		}
414		if len(header) != 4 || header[0] != "usage_id" || header[1] != "customer_id" ||
415			header[2] != "time" || header[3] != "quantity" {
416			return nil, []string{fmt.Sprintf("表头必须是 %s，实际为 %s", usageHeader, strings.Join(header, ","))}
417		}
418	
419		var rows []*parsedRow
420		var problems []string
421		line := 1
422		for {
423			rec, err := cr.Read()
424			if err == io.EOF {
425				break
426			}
427			line++
428			if err != nil {
429				problems = append(problems, fmt.Sprintf("第 %d 行：CSV 格式错误：%v", line, err))
430				if pe, ok := err.(*csv.ParseError); ok && pe.Err == csv.ErrFieldCount {
431					// 字段数错误后继续读取仍可能拿到错乱记录，直接终止解析。
432					break
433				}
434				continue
435			}
436			for i := range rec {
437				rec[i] = strings.TrimSpace(rec[i])
438			}
439	
440			id, custID, ts, qtyText := rec[0], rec[1], rec[2], rec[3]
441			if id == "" {
442				problems = append(problems, fmt.Sprintf("第 %d 行：用量标识不能为空", line))
443				continue
444			}
445			if custID == "" {
446				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识不能为空", line))
447				continue
448			}
449			t, err := time.Parse(time.RFC3339, ts)
450			if err != nil {
451				problems = append(problems, fmt.Sprintf("第 %d 行：时间 %q 不是 RFC3339 格式：%v", line, ts, err))
452				continue
453			}
454			qty, err := strconv.ParseInt(qtyText, 10, 64)
455			if err != nil {
456				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %q 不是有符号 64 位整数", line, qtyText))
457				continue
458			}
459			if qty <= 0 {
460				problems = append(problems, fmt.Sprintf("第 %d 行：数量必须是正整数，收到 %d", line, qty))
461				continue
462			}
463	
464			rows = append(rows, &parsedRow{
465				line: line,
466				rec:  usageRecord{ID: id, CustomerID: custID, Time: ts, Quantity: qty},
467				t:    t,
468			})
469		}
470		return rows, problems
471	}
472	
473	// sameUsage 按（客户、解析后的时间点、数量）判定两条记录内容是否相同，
474	// 时间比较的是瞬间，因此 Z 与 +08:00 表示同一时刻视为相同。
475	func sameUsage(existing *usageRecord, candidate *usageRecord, candidateT time.Time) bool {
476		if existing.CustomerID != candidate.CustomerID || existing.Quantity != candidate.Quantity {
477			return false
478		}
479		et, err := time.Parse(time.RFC3339, existing.Time)
480		if err != nil {
481			return existing.Time == candidate.Time
482		}
483		return et.Equal(candidateT)
484	}
485	
486	// validMonth 严格校验 YYYY-MM（月份两位、01..12）。
487	func validMonth(m string) bool {
488		t, err := time.Parse("2006-01", m)
489		if err != nil || t.Format("2006-01") != m || t.Year() < 1 {
490			return false
491		}
492		return true
493	}
494	
495	// inMonth 判定一条 RFC3339 时间（换算 UTC 后）是否落在给定自然月。
496	func inMonth(rfc3339, month string) bool {
497		t, err := time.Parse(time.RFC3339, rfc3339)
498		if err != nil {
499			return false
500		}
501		return t.UTC().Format("2006-01") == month
502	}
503	
504	// utcMonth 返回 RFC3339 时间换算 UTC 后的自然月（YYYY-MM）。
505	// 入参时间均已在载入/导入时校验为 RFC3339。
506	func utcMonth(rfc3339 string) string {
507		t, _ := time.Parse(time.RFC3339, rfc3339)
508		return t.UTC().Format("2006-01")
509	}
