511	func cmdBillSettle(dir, customerID, month string) error {
512		if !validMonth(month) {
513			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
514		}
515		s, err := loadStore(dir)
516		if err != nil {
517			return err
518		}
519		cust, ok := s.Customers[customerID]
520		if !ok {
521			return fmt.Errorf("客户标识 %q 不存在", customerID)
522		}
523	
524		// 暂停月无论方案月费多少都拒绝结算：不封账、不生成零金额账单。
525		if s.isSuspendedMonth(customerID, month) {
526			return fmt.Errorf("客户 %s 的 %s 处于暂停区间，暂停服务期间不产生月费账单，拒绝结算且不封账", customerID, month)
527		}
528	
529		key := billKey(customerID, month)
530		if existing, ok := s.Bills[key]; ok {
531			// 幂等：同一客户同一月份重复结算，直接返回原账单，
532			// 不重新计费、不产生新账单或调整、不落盘。
533			fmt.Fprintf(stdout, "客户 %s 的 %s 已结算，返回原账单（幂等，不重新计费）：\n\n", customerID, month)
534			printBill(existing, cust, s)
535			return nil
536		}
537	
538		// 归集该客户 UTC 自然月内的全部有效（未撤回）用量，区间为左闭右开
539		// [月初, 下月初)。有效方案月费大于 0 的阶梯客户即使无用量也须出账
540		// （收取一次整月月费）；月费为 0 的方案与固定单价客户无用量时仍拒绝
541		// 结算且不封账。
542		inMonthRecs := monthUsage(s, customerID, month)
543		if len(inMonthRecs) == 0 && !monthlyFeeBillable(s, cust, month) {
544			return fmt.Errorf("客户 %s 在 %s 没有用量，拒绝结算且不封账", customerID, month)
545		}
546	
547		// 绑定阶梯方案的客户走按月累计分档计价；固定单价客户保持原路径。
548		if cust.PlanID != "" {
549			return settleTiered(s, cust, month, inMonthRecs)
550		}
551	
552		b, err := buildFixedBill(cust, month, inMonthRecs)
553		if err != nil {
554			return fmt.Errorf("%v，拒绝结算且不封账", err)
555		}
556		s.Bills[key] = b
557	
558		// 账单与封账状态在同一次原子保存中一起持久化；保存失败则一切不生效。
559		if err := s.save(); err != nil {
560			delete(s.Bills, key)
561			return err
562		}
563		fmt.Fprintf(stdout, "结算完成，客户 %s 的 %s 已封账：\n\n", customerID, month)
564		printBill(b, cust, s)
565		return nil
566	}
