568	func cmdBillShow(dir, customerID, month string) error {
569		if !validMonth(month) {
570			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
571		}
572		s, err := loadStore(dir)
573		if err != nil {
574			return err
575		}
576		cust, ok := s.Customers[customerID]
577		if !ok {
578			return fmt.Errorf("客户标识 %q 不存在", customerID)
579		}
580		b, ok := s.Bills[billKey(customerID, month)]
581		if !ok {
582			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
583		}
584		printBill(b, cust, s)
585		return nil
586	}
