588	// monthUsage 归集客户在某 UTC 自然月（左闭右开 [月初, 下月初)）内的全部
589	// 有效（未撤回）用量，并按计价顺序（解析后的时间点升序、同一时间按标识
590	// 字典序）排列。已撤回用量不计费用，不参与单笔及批量结算；阶梯计价将剩余
591	// 记录按原有时间点及标识顺序从零累计重新分档。
592	func monthUsage(s *state, customerID, month string) []*usageRecord {
593		var recs []*usageRecord
594		for _, u := range s.Usage {
595			if s.isWithdrawn(u.ID) {
596				continue
597			}
598			if u.CustomerID == customerID && inMonth(u.Time, month) {
599				recs = append(recs, u)
600			}
601		}
602		sortByInstant(recs)
603		return recs
604	}
