606	// buildFixedBill 为固定单价客户构造账单（不落盘）：逐条 数量×单价 并汇总，
607	// 全程整数运算，任何一步溢出都返回错误。recs 须已按计价顺序排列。
608	func buildFixedBill(cust *customer, month string, recs []*usageRecord) (*bill, error) {
609		lines := make([]billLine, 0, len(recs))
610		var totalQty, totalFee int64
611		for _, u := range recs {
612			lineFee, err := mul64(u.Quantity, cust.Price)
613			if err != nil {
614				return nil, fmt.Errorf("用量 %s：数量 %d × 单价 %d 金额溢出", u.ID, u.Quantity, cust.Price)
615			}
616			if totalQty, err = add64(totalQty, u.Quantity); err != nil {
617				return nil, fmt.Errorf("汇总数量溢出有符号 64 位整数范围")
618			}
619			if totalFee, err = add64(totalFee, lineFee); err != nil {
620				return nil, fmt.Errorf("汇总金额溢出有符号 64 位整数范围")
621			}
622			lines = append(lines, billLine{
623				UsageID:  u.ID,
624				Time:     u.Time,
625				Quantity: u.Quantity,
626				LineFee:  lineFee,
627			})
628		}
629		return &bill{
630			ID:         stableBillID(cust.ID, month),
631			CustomerID: cust.ID,
632			Month:      month,
633			TotalQty:   totalQty,
634			UnitPrice:  cust.Price,
635			TotalFee:   totalFee,
636			Lines:      lines,
637			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
638		}, nil
639	}
640	
641	func sortByInstant(us []*usageRecord) {
642		// 入参时间均已在载入/导入时校验为 RFC3339。
643		sort.Slice(us, func(i, j int) bool {
644			ti, _ := time.Parse(time.RFC3339, us[i].Time)
645			tj, _ := time.Parse(time.RFC3339, us[j].Time)
646			ui, uj := ti.UTC(), tj.UTC()
647			if !ui.Equal(uj) {
648				return ui.Before(uj)
649			}
650			return us[i].ID < us[j].ID
651		})
652	}
