742	// historyEvents 把调整与撤销展开为按操作序号排序的可读历史条目。
743	func historyEvents(adjs []*adjustment) []string {
744		type event struct {
745			seq  int64
746			text string
747		}
748		var events []event
749		for _, a := range adjs {
750			events = append(events, event{a.Seq, fmt.Sprintf("调整 %s：%s %+d 分（%s），原因：%s，当前状态：%s",
751				a.ID, adjustKind(a.Amount), a.Amount, moneyFen(a.Amount), a.Reason, adjustStatus(a))})
752			if a.Revoked {
753				events = append(events, event{a.RevokeSeq, fmt.Sprintf("撤销 %s：原因：%s（关联调整 %s 的%s %+d 分）",
754					a.ID, a.RevokeReason, a.ID, adjustKind(a.Amount), a.Amount)})
755			}
756		}
757		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
758		out := make([]string, len(events))
759		for i, ev := range events {
760			out[i] = ev.text
761		}
762		return out
763	}
