779	// paymentHistoryEvents 把收款登记、分配更正与撤销展开为按操作序号排序的
780	// 可读历史条目；month 为当前展示账单所在月份。收款事件展示首次登记时在
781	// 本账单的分配，更正事件展示本账单分配的前后变化，撤销事件展示被整笔取消
782	// 的最新分配。
783	func paymentHistoryEvents(s *state, pays []*payment, month string) []string {
784		type event struct {
785			seq  int64
786			text string
787		}
788		var events []event
789		for _, p := range pays {
790			alloc := p.amountFor(month)
791			events = append(events, event{p.Seq, fmt.Sprintf("收款 %s：总额 %d 分（%s），本账单分配 %d 分（%s），备注：%s，当前状态：%s（客户 %s）",
792				p.ID, p.Total, moneyFen(p.Total), alloc, moneyFen(alloc), p.Note, paymentStatus(p), p.CustomerID)})
793			// 以首次登记分配为起点，按序号回放该收款在本账单的分配变化。
794			running := alloc
795			for _, c := range correctionsFor(s, p.ID) {
796				after := allocAmountFor(c.Allocations, month)
797				if running == 0 && after == 0 {
798					continue // 本次更正不涉及本账单
799				}
800				events = append(events, event{c.Seq, fmt.Sprintf("更正 %s：原因：%s（关联收款 %s，本账单分配 %d 分 → %d 分）",
801					c.ID, c.Reason, p.ID, running, after)})
802				running = after
803			}
804			if p.Revoked {
805				// 整笔撤销取消的是撤销时的最新分配。
806				events = append(events, event{p.RevokeSeq, fmt.Sprintf("撤销收款 %s：原因：%s（关联收款 %s，总额 %d 分，本账单分配 %d 分）",
807					p.ID, p.RevokeReason, p.ID, p.Total, running)})
808			}
809			// 退款在其发生序号减少本账单实收；退款不可撤销，记录永久保留。
810			for _, r := range refundsFor(s, p.ID) {
811				amt := allocAmountFor(r.Allocations, month)
812				if amt <= 0 {
813					continue // 本次退款不涉及本账单
814				}
815				events = append(events, event{r.Seq, fmt.Sprintf("退款 %s：原因：%s（关联收款 %s，本账单退款 %d 分（%s））",
816					r.ID, r.Reason, p.ID, amt, moneyFen(amt))})
817			}
818		}
819		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
820		out := make([]string, len(events))
821		for i, ev := range events {
822			out[i] = ev.text
823		}
824		return out
825	}
826	
827	func paymentStatus(p *payment) string {
828		if p.Revoked {
829			return "已撤销"
830		}
831		return "实收中"
832	}
