834	// parseAmount 解析调整金额：有符号 64 位整数、非零（正数补收、负数减免）。
835	func parseAmount(text string) (int64, error) {
836		text = strings.TrimSpace(text)
837		amount, err := strconv.ParseInt(text, 10, 64)
838		if err != nil {
839			return 0, fmt.Errorf("调整金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
840		}
841		if amount == 0 {
842			return 0, fmt.Errorf("调整金额不能为零分（正数补收、负数减免）")
843		}
844		return amount, nil
845	}
