847	func cmdBillAdjust(dir, customerID, month, adjID, amountText, reason string) error {
848		if !validMonth(month) {
849			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
850		}
851		if strings.TrimSpace(adjID) == "" {
852			return fmt.Errorf("调整标识不能为空")
853		}
854		amount, err := parseAmount(amountText)
855		if err != nil {
856			return err
857		}
858		if strings.TrimSpace(reason) == "" {
859			return fmt.Errorf("调整原因不能为空")
860		}
861	
862		s, err := loadStore(dir)
863		if err != nil {
864			return err
865		}
866		if _, ok := s.Customers[customerID]; !ok {
867			return fmt.Errorf("客户标识 %q 不存在", customerID)
868		}
869		b, ok := s.Bills[billKey(customerID, month)]
870		if !ok {
871			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），费用调整只能作用于已存在账单", customerID, month)
872		}
873	
874		if existing, ok := s.Adjustments[adjID]; ok {
875			// 相同标识按客户、月份、金额、原因判断重复：内容相同返回已保存
876			// 记录，不再次增减应付；已撤销的重放仍返回已撤销状态，不重新生效。
877			if existing.CustomerID == customerID && existing.Month == month &&
878				existing.Amount == amount && existing.Reason == reason {
879				fmt.Fprintf(stdout, "调整 %q 已存在且内容相同，返回已保存记录（不重复增减应付）：\n\n", adjID)
880				printAdjustment(existing, s)
881				return nil
882			}
883			return fmt.Errorf("调整标识 %q 已存在但内容不同（已有：客户=%s 月份=%s 金额=%d 原因=%q），拒绝复用",
884				adjID, existing.CustomerID, existing.Month, existing.Amount, existing.Reason)
885		}
886	
887		// 应付可行性预检：原总金额 + 全部未撤销调整 + 本次金额必须落在
888		// [0, 有符号 64 位最大值] 内，且不得低于已登记实收，否则拒绝且
889		// 不占用该调整标识。
890		_, payable, err := billTotals(b, adjustmentsFor(s, customerID, month))
891		if err != nil {
892			return fmt.Errorf("账单当前应付异常，拒绝调整: %w", err)
893		}
894		received, err := paymentReceived(s, customerID, month)
895		if err != nil {
896			return fmt.Errorf("实收累计异常，拒绝调整: %w", err)
897		}
898		newPayable, err := addSigned64(payable, amount)
899		if err != nil {
900			return fmt.Errorf("调整后当前应付超出有符号 64 位最大值（当前 %d 分，本次 %+d 分），拒绝调整", payable, amount)
901		}
902		if newPayable < 0 {
903			return fmt.Errorf("调整后当前应付将为 %d 分（小于 0，当前 %d 分，本次 %+d 分），拒绝调整", newPayable, payable, amount)
904		}
905		if newPayable < received {
906			return fmt.Errorf("调整后当前应付 %d 分将低于实收 %d 分（当前 %d 分，本次 %+d 分），拒绝调整；可先撤销误登记的收款再重试",
907				newPayable, received, payable, amount)
908		}
909	
910		a := &adjustment{
911			ID:         adjID,
912			CustomerID: customerID,
913			Month:      month,
914			Amount:     amount,
915			Reason:     reason,
916			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
917		}
918		s.NextSeq++
919		a.Seq = s.NextSeq
920		s.Adjustments[adjID] = a
921	
922		// 调整记录与序号在同一次原子保存中持久化；保存失败则一切不生效，
923		// 该调整标识不被占用。
924		if err := s.save(); err != nil {
925			delete(s.Adjustments, adjID)
926			s.NextSeq--
927			return err
928		}
929		fmt.Fprintf(stdout, "已登记%s调整 %q，客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
930			adjustKind(amount), adjID, customerID, month, newPayable, moneyFen(newPayable))
931		printAdjustment(a, s)
932		return nil
933	}
934	
935	func cmdBillRevoke(dir, adjID, reason string) error {
936		if strings.TrimSpace(adjID) == "" {
937			return fmt.Errorf("调整标识不能为空")
938		}
939		if strings.TrimSpace(reason) == "" {
940			return fmt.Errorf("撤销原因不能为空")
941		}
942	
943		s, err := loadStore(dir)
944		if err != nil {
945			return err
946		}
947		a, ok := s.Adjustments[adjID]
948		if !ok {
949			return fmt.Errorf("调整标识 %q 不存在，无法撤销", adjID)
950		}
951	
952		if a.Revoked {
953			// 相同标识与相同原因重复撤销：幂等成功，不新增记录；
954			// 改用其他原因则拒绝。
955			if a.RevokeReason == reason {
956				fmt.Fprintf(stdout, "调整 %q 已撤销且撤销原因相同，幂等返回（不新增记录）：\n\n", adjID)
957				printAdjustment(a, s)
958				return nil
959			}
960			return fmt.Errorf("调整 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", adjID, a.RevokeReason)
961		}
962	
963		// 撤销只取消该笔调整的金额影响；若撤销后当前应付越界或低于实收则
964		// 拒绝，该调整仍保持有效，可先撤销误登记的收款或在其他合法调整
965		// 改变余额后重试。
966		b := s.Bills[billKey(a.CustomerID, a.Month)] // 载入时已校验存在
967		_, payable, err := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
968		if err != nil {
969			return fmt.Errorf("账单当前应付异常，拒绝撤销: %w", err)
970		}
971		received, err := paymentReceived(s, a.CustomerID, a.Month)
972		if err != nil {
973			return fmt.Errorf("实收累计异常，拒绝撤销: %w", err)
974		}
975		neg, err := neg64(a.Amount)
976		if err != nil {
977			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值，拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试")
978		}
979		newPayable, err := addSigned64(payable, neg)
980		if err != nil {
981			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值（当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
982				payable, a.Amount)
983		}
984		if newPayable < 0 {
985			return fmt.Errorf("撤销后当前应付将为 %d 分（小于 0，当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
986				newPayable, payable, a.Amount)
987		}
988		if newPayable < received {
989			return fmt.Errorf("撤销后当前应付 %d 分将低于实收 %d 分（当前 %d 分，取消 %+d 分），拒绝撤销；可先撤销误登记的收款再重试",
990				newPayable, received, payable, a.Amount)
991		}
992	
993		a.Revoked = true
994		a.RevokeReason = reason
995		a.RevokedAt = time.Now().UTC().Format(time.RFC3339)
996		s.NextSeq++
997		a.RevokeSeq = s.NextSeq
998	
999		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
1000		if err := s.save(); err != nil {
1001			a.Revoked = false
1002			a.RevokeReason = ""
1003			a.RevokedAt = ""
1004			a.RevokeSeq = 0
1005			s.NextSeq--
1006			return err
1007		}
1008		fmt.Fprintf(stdout, "已撤销调整 %q（%s %+d 分），客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
1009			adjID, adjustKind(a.Amount), a.Amount, a.CustomerID, a.Month, newPayable, moneyFen(newPayable))
1010		printAdjustment(a, s)
1011		return nil
1012	}
