1031	// parsePositiveAmount 解析收款金额：正整数分（不接受零、负数、小数）。
1032	func parsePositiveAmount(text string) (int64, error) {
1033		text = strings.TrimSpace(text)
1034		amount, err := strconv.ParseInt(text, 10, 64)
1035		if err != nil {
1036			return 0, fmt.Errorf("收款金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
1037		}
1038		if amount <= 0 {
1039			return 0, fmt.Errorf("收款金额必须是正整数分，收到 %d", amount)
1040		}
1041		return amount, nil
1042	}
