1057	func cmdBillRemit(dir, customerID, payID, totalText, note string, allocArgs []string) error {
1058		total, err := parsePositiveAmount(totalText)
1059		if err != nil {
1060			return err
1061		}
1062		allocs, err := parseAllocations(allocArgs)
1063		if err != nil {
1064			return err
1065		}
1066		// 分配合计必须等于总额，全程整数运算，溢出拒绝。
1067		var sum int64
1068		for _, al := range allocs {
1069			sum, err = add64(sum, al.Amount)
1070			if err != nil {
1071				return fmt.Errorf("分配金额合计溢出有符号 64 位整数范围，拒绝登记")
1072			}
1073		}
1074		if sum != total {
1075			return fmt.Errorf("分配合计 %d 分与收款总额 %d 分不一致，拒绝登记", sum, total)
1076		}
1077		return registerPayment(dir, customerID, payID, total, note, allocs)
1078	}
