1082	// cmdBillRemitAuto 登记一笔自动分配汇款：调用方只提供客户、收款标识、总金额
1083	// 与备注，月份金额由工具确定——首次登记只选择该客户当前已有账单，按 UTC
1084	// 账期月升序依次偿还当前未收余额（调整、最新收款分配、撤销及退款后的净额），
1085	// 跳过余额为 0 的月份，前一月份还清后才分配下一月，最后一月可部分偿还；
1086	// 不补结算、不跨客户、不留未分配款项。无欠款或总金额超过全部欠款时整笔拒绝。
1087	func cmdBillRemitAuto(dir, customerID, payID, totalText, note string) error {
1088		total, err := parsePositiveAmount(totalText)
1089		if err != nil {
1090			return err
1091		}
1092		if strings.TrimSpace(payID) == "" {
1093			return fmt.Errorf("收款标识不能为空")
1094		}
1095		if strings.TrimSpace(note) == "" {
1096			return fmt.Errorf("收款备注不能为空")
1097		}
1098	
1099		s, err := loadStore(dir)
1100		if err != nil {
1101			return err
1102		}
1103		if _, ok := s.Customers[customerID]; !ok {
1104			return fmt.Errorf("客户标识 %q 不存在", customerID)
1105		}
1106	
1107		if existing, ok := s.Payments[payID]; ok {
1108			// 自动登记按客户、总金额、备注判重：相同请求返回原收款及当前状态，
1109			// 不写盘、不重新分配、不增加序号；已撤销或已退款的仍返回当前状态，
1110			// 不恢复旧分配或已退、已撤销金额。
1111			if existing.Auto && existing.CustomerID == customerID &&
1112				existing.Total == total && existing.Note == note {
1113				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同（自动分配登记），返回原收款及当前状态（不写盘、不重新分配、不增加序号）：\n\n", payID)
1114				printAutoPayment(s, existing)
1115				return nil
1116			}
1117			// 同一标识在自动与显式分配登记间复用拒绝；内容不同同样拒绝。
1118			if !existing.Auto {
1119				return fmt.Errorf("收款标识 %q 已由显式分配登记占用（已有：客户=%s 总额=%d 备注=%q 分配=%s），自动与显式分配登记之间不得复用，拒绝",
1120					payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1121			}
1122			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q），拒绝复用",
1123				payID, existing.CustomerID, existing.Total, existing.Note)
1124		}
1125	
1126		// 首次登记的自动分配由 remit-auto 与整批导入共用的 autoAllocate 确定。
1127		allocs, err := autoAllocate(s, customerID, total)
1128		if err != nil {
1129			return err
1130		}
1131	
1132		// 成功保存为一笔普通收款及首次自动分配：占用一个账后全局序号，
1133		// 不按月份拆成多笔；可沿用分配更正、整笔撤销、部分退款及退款后
1134		// 固定分配的规则。
1135		p := &payment{
1136			ID:          payID,
1137			CustomerID:  customerID,
1138			Total:       total,
1139			Note:        note,
1140			Allocations: allocs,
1141			Auto:        true,
1142			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1143		}
1144		s.NextSeq++
1145		p.Seq = s.NextSeq
1146		s.Payments[payID] = p
1147	
1148		// 收款记录、首次分配与序号在同一次原子保存中持久化；保存失败则一切
1149		// 不生效，该收款标识与序号不被占用，可原样重试。
1150		if err := s.save(); err != nil {
1151			delete(s.Payments, payID)
1152			s.NextSeq--
1153			return err
1154		}
1155		fmt.Fprintf(stdout, "已按最早欠款账期自动分配并登记收款 %q（总额 %d 分，%s；一次操作，占用一个账后序号）：\n\n",
1156			payID, total, moneyFen(total))
1157		printAutoPayment(s, p)
1158		return nil
1159	}
