1161	// printAutoPayment 输出一笔自动分配登记的收款：收款标识、总额、备注、当前
1162	// 状态、首次分配与最新分配，以及这两份分配所涉月份的当前余额。首次分配
1163	// 永久保留；最新分配经更正变化时以最新为准，退款与撤销不改变首次分配。
1164	func printAutoPayment(s *state, p *payment) {
1165		current := currentAllocations(s, p)
1166		fmt.Fprintf(stdout, "收款标识：%s\n", p.ID)
1167		fmt.Fprintf(stdout, "客户：%s\n", p.CustomerID)
1168		fmt.Fprintf(stdout, "收款总额：%d 分（%s）\n", p.Total, moneyFen(p.Total))
1169		fmt.Fprintf(stdout, "备注：%s\n", p.Note)
1170		if p.Revoked {
1171			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", p.RevokeReason)
1172		} else {
1173			fmt.Fprintf(stdout, "当前状态：实收中\n")
1174		}
1175		fmt.Fprintf(stdout, "首次分配（登记时按最早欠款账期自动确定，永久保留）：%s\n", formatAllocations(p.Allocations))
1176		if sameAllocations(current, p.Allocations) {
1177			fmt.Fprintf(stdout, "最新分配：%s（与首次分配相同）\n", formatAllocations(current))
1178		} else {
1179			fmt.Fprintf(stdout, "最新分配（经更正，以最新为准）：%s\n", formatAllocations(current))
1180		}
1181		fmt.Fprintln(stdout, "首次与最新分配所涉月份当前余额：")
1182		for _, m := range unionMonths(p.Allocations, current) {
1183			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1184			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1185			received, _ := paymentReceived(s, p.CustomerID, m)
1186			fmt.Fprintf(stdout, "  月份 %s：首次分配 %d 分，最新分配 %d 分；当前应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1187				m, allocAmountFor(p.Allocations, m), allocAmountFor(current, m),
1188				payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1189		}
1190	}
