1192	// parseAllocations 解析 <YYYY-MM:金额分> 形式的分配列表：至少一项，
1193	// 月份不得重复，每项金额为正整数分。
1194	func parseAllocations(args []string) ([]paymentAllocation, error) {
1195		if len(args) == 0 {
1196			return nil, fmt.Errorf("分配列表不能为空，至少需要一项 <YYYY-MM:金额分>")
1197		}
1198		seen := make(map[string]bool)
1199		allocs := make([]paymentAllocation, 0, len(args))
1200		for _, arg := range args {
1201			parts := strings.Split(arg, ":")
1202			if len(parts) != 2 {
1203				return nil, fmt.Errorf("分配项 %q 格式非法，应为 YYYY-MM:金额分（如 2026-09:500）", arg)
1204			}
1205			month := strings.TrimSpace(parts[0])
1206			if !validMonth(month) {
1207				return nil, fmt.Errorf("分配项 %q 的月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", arg, parts[0])
1208			}
1209			if seen[month] {
1210				return nil, fmt.Errorf("分配月份 %s 重复，拒绝登记", month)
1211			}
1212			seen[month] = true
1213			amount, err := parsePositiveAmount(parts[1])
1214			if err != nil {
1215				return nil, fmt.Errorf("分配项 %q 的金额无效: %w", arg, err)
1216			}
1217			allocs = append(allocs, paymentAllocation{Month: month, Amount: amount})
1218		}
1219		return allocs, nil
1220	}
1221	
1222	// registerPayment 是 bill pay 与 bill remit 共用的收款登记核心：
1223	// 先整体校验再整笔生效，任何一项不合法都不落盘、不占用收款标识。
1224	func registerPayment(dir, customerID, payID string, total int64, note string, allocs []paymentAllocation) error {
1225		if strings.TrimSpace(payID) == "" {
1226			return fmt.Errorf("收款标识不能为空")
1227		}
1228		if strings.TrimSpace(note) == "" {
1229			return fmt.Errorf("收款备注不能为空")
1230		}
1231		// 分配顺序不影响收款身份：统一按月份升序保存与比较。
1232		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1233	
1234		s, err := loadStore(dir)
1235		if err != nil {
1236			return err
1237		}
1238		if _, ok := s.Customers[customerID]; !ok {
1239			return fmt.Errorf("客户标识 %q 不存在", customerID)
1240		}
1241		for _, al := range allocs {
1242			if _, ok := s.Bills[billKey(customerID, al.Month)]; !ok {
1243				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），收款只能登记到已存在账单", customerID, al.Month)
1244			}
1245		}
1246	
1247		if existing, ok := s.Payments[payID]; ok {
1248			// 自动与显式分配登记之间不得复用同一收款标识：标识由 bill remit-auto
1249			// 占用时，bill pay / bill remit 一律拒绝（即使内容碰巧相同）。
1250			if existing.Auto {
1251				return fmt.Errorf("收款标识 %q 已由自动分配登记占用（已有：客户=%s 总额=%d 备注=%q 分配=%s），自动与显式分配登记之间不得复用，拒绝",
1252					payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1253			}
1254			// 相同标识按客户、总额、备注与月份-金额对应关系判断重复：内容相同
1255			// 返回已保存记录，不再次计入实收，也不受当前余额变化影响；
1256			// 已撤销的重放仍返回已撤销状态，不恢复实收。
1257			if samePaymentContent(existing, customerID, total, note, allocs) {
1258				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同，返回已保存记录（不重复计入实收）：\n\n", payID)
1259				printPayment(existing, s)
1260				return nil
1261			}
1262			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q 分配=%s），拒绝复用",
1263				payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1264		}
1265	
1266		// 首次登记：每项分配不得超过对应账单的未收余额，全部合法才整笔生效。
1267		for _, al := range allocs {
1268			b := s.Bills[billKey(customerID, al.Month)]
1269			_, payable, err := billTotals(b, adjustmentsFor(s, customerID, al.Month))
1270			if err != nil {
1271				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝登记收款: %w", customerID, al.Month, err)
1272			}
1273			received, err := paymentReceived(s, customerID, al.Month)
1274			if err != nil {
1275				return fmt.Errorf("客户 %s 的 %s 实收累计溢出有符号 64 位整数范围，拒绝登记收款: %w", customerID, al.Month, err)
1276			}
1277			if payable == 0 {
1278				return fmt.Errorf("客户 %s 的 %s 当前应付为 0 分，不能登记正额收款", customerID, al.Month)
1279			}
1280			if al.Amount > payable-received {
1281				return fmt.Errorf("分配 %d 分超过未收余额 %d 分（客户 %s 的 %s：当前应付 %d 分，实收 %d 分），拒绝登记",
1282					al.Amount, payable-received, customerID, al.Month, payable, received)
1283			}
1284		}
1285	
1286		p := &payment{
1287			ID:          payID,
1288			CustomerID:  customerID,
1289			Total:       total,
1290			Note:        note,
1291			Allocations: allocs,
1292			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1293		}
1294		s.NextSeq++
1295		p.Seq = s.NextSeq
1296		s.Payments[payID] = p
1297	
1298		// 收款记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1299		// 一切不生效，该收款标识不被占用。
1300		if err := s.save(); err != nil {
1301			delete(s.Payments, payID)
1302			s.NextSeq--
1303			return err
1304		}
1305		fmt.Fprintf(stdout, "已登记收款 %q（总额 %d 分，%s）：\n", payID, total, moneyFen(total))
1306		printAllocationBalances(s, p, allocs)
1307		fmt.Fprintln(stdout)
1308		printPayment(p, s)
1309		return nil
1310	}
1311	
1312	// samePaymentContent 按客户、总额、备注与月份-金额对应关系判定两笔收款
1313	// 内容相同；分配顺序不影响身份。判重依据首次登记内容，不受后续更正影响。
1314	func samePaymentContent(p *payment, customerID string, total int64, note string, allocs []paymentAllocation) bool {
1315		if p.CustomerID != customerID || p.Total != total || p.Note != note {
1316			return false
1317		}
1318		return sameAllocations(p.Allocations, allocs)
1319	}
1320	
1321	// sameAllocations 判定两个分配列表的月份-金额对应关系相同（顺序无关）。
1322	func sameAllocations(a, b []paymentAllocation) bool {
1323		if len(a) != len(b) {
1324			return false
1325		}
1326		for _, al := range b {
1327			if allocAmountFor(a, al.Month) != al.Amount {
1328				return false
1329			}
1330		}
1331		return true
1332	}
1333	
1334	// formatAllocations 以 "2026-09:500,2026-10:300" 形式展示分配列表。
1335	func formatAllocations(allocs []paymentAllocation) string {
1336		parts := make([]string, len(allocs))
1337		for i, al := range allocs {
1338			parts[i] = fmt.Sprintf("%s:%d", al.Month, al.Amount)
1339		}
1340		return strings.Join(parts, ",")
1341	}
1342	
1343	// printAllocationBalances 输出给定分配列表每个分配月份当前的实收与未收余额。
1344	func printAllocationBalances(s *state, p *payment, allocs []paymentAllocation) {
1345		for _, al := range allocs {
1346			b := s.Bills[billKey(p.CustomerID, al.Month)] // 载入时已校验存在
1347			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, al.Month))
1348			received, _ := paymentReceived(s, p.CustomerID, al.Month)
1349			fmt.Fprintf(stdout, "  月份 %s：分配 %d 分，实收 %d 分（%s），未收余额 %d 分（%s）\n",
1350				al.Month, al.Amount, received, moneyFen(received), payable-received, moneyFen(payable-received))
1351		}
1352	}
1353	
1354	func cmdBillUnpay(dir, payID, reason string) error {
1355		if strings.TrimSpace(payID) == "" {
1356			return fmt.Errorf("收款标识不能为空")
1357		}
1358		if strings.TrimSpace(reason) == "" {
1359			return fmt.Errorf("撤销原因不能为空")
1360		}
1361	
1362		s, err := loadStore(dir)
1363		if err != nil {
1364			return err
1365		}
1366		p, ok := s.Payments[payID]
1367		if !ok {
1368			return fmt.Errorf("收款标识 %q 不存在，无法撤销", payID)
1369		}
1370	
1371		if p.Revoked {
1372			// 相同标识与相同原因重复撤销：幂等成功，不新增历史；
1373			// 改用其他原因则拒绝。
1374			if p.RevokeReason == reason {
1375				fmt.Fprintf(stdout, "收款 %q 已撤销且撤销原因相同，幂等返回（不新增历史）：\n\n", payID)
1376				printPayment(p, s)
1377				return nil
1378			}
1379			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", payID, p.RevokeReason)
1380		}
1381	
1382		// 首次退款后该收款的最新分配固定，拒绝整笔撤销；退款记录永久保留且
1383		// 不可撤销，实收按扣除退款后的余额继续计算。无退款的收款仍按原规则
1384		// 处理。
1385		if paymentHasRefunds(s, payID) {
1386			return fmt.Errorf("收款 %q 已发生退款，最新分配已固定，拒绝整笔撤销；如需退回余款请继续登记部分退款", payID)
1387		}
1388	
1389		// 撤销整笔生效：取消该笔在全部分配月份上的最新实收（经更正的以最新
1390		// 分配为准），不接受部分撤销；不改变应付、其他收款或调整，原收款、
1391		// 分配、更正与撤销原因永久保留。
1392		p.Revoked = true
1393		p.RevokeReason = reason
1394		p.RevokedAt = time.Now().UTC().Format(time.RFC3339)
1395		s.NextSeq++
1396		p.RevokeSeq = s.NextSeq
1397	
1398		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
1399		if err := s.save(); err != nil {
1400			p.Revoked = false
1401			p.RevokeReason = ""
1402			p.RevokedAt = ""
1403			p.RevokeSeq = 0
1404			s.NextSeq--
1405			return err
1406		}
1407		fmt.Fprintf(stdout, "已撤销收款 %q（总额 %d 分，%s），取消最新分配：\n", payID, p.Total, moneyFen(p.Total))
1408		printAllocationBalances(s, p, currentAllocations(s, p))
1409		fmt.Fprintln(stdout)
1410		printPayment(p, s)
1411		return nil
1412	}
1413	
1414	// printPayment 输出单笔收款记录：总额、首次登记的全部分配（永久保留，
1415	// 判重依据）与当前状态；经历过更正时同时展示当前生效的最新分配。
1416	// 各月应付/实收取自当前库状态。
1417	func printPayment(p *payment, s *state) {
1418		fmt.Fprintf(stdout, "收款标识：%s\n", p.ID)
1419		fmt.Fprintf(stdout, "客户：%s\n", p.CustomerID)
1420		fmt.Fprintf(stdout, "收款总额：%d 分（%s）\n", p.Total, moneyFen(p.Total))
1421		fmt.Fprintf(stdout, "备注：%s\n", p.Note)
1422		if p.Revoked {
1423			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", p.RevokeReason)
1424		} else {
1425			fmt.Fprintf(stdout, "当前状态：实收中\n")
1426		}
1427		fmt.Fprintln(stdout, "分配明细（首次登记，永久保留）：")
1428		for i, al := range p.Allocations {
1429			b := s.Bills[billKey(p.CustomerID, al.Month)] // 载入时已校验存在
1430			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, al.Month))
1431			received, _ := paymentReceived(s, p.CustomerID, al.Month)
1432			fmt.Fprintf(stdout, "  %d. 月份 %s：分配 %d 分（%s）；当前应付 %d 分，实收合计 %d 分，未收余额 %d 分\n",
1433				i+1, al.Month, al.Amount, moneyFen(al.Amount), payable, received, payable-received)
1434		}
1435		if corrs := correctionsFor(s, p.ID); len(corrs) > 0 {
1436			fmt.Fprintf(stdout, "当前分配（经 %d 次更正，以最新为准）：%s\n",
1437				len(corrs), formatAllocations(currentAllocations(s, p)))
1438		}
1439		if refs := refundsFor(s, p.ID); len(refs) > 0 {
1440			current := currentAllocations(s, p)
1441			fmt.Fprintf(stdout, "退款记录（%d 笔，永久保留、不可撤销；首次退款后最新分配已固定）：\n", len(refs))
1442			for _, r := range refs {
1443				fmt.Fprintf(stdout, "  退款 %s：%s，原因：%s\n", r.ID, formatAllocations(r.Allocations), r.Reason)
1444			}
1445			fmt.Fprintln(stdout, "各月剩余可退额（最新分配减累计退款）：")
1446			for _, al := range current {
1447				refunded := refundedForMonth(s, p.ID, al.Month)
1448				fmt.Fprintf(stdout, "  月份 %s：分配 %d 分，累计已退 %d 分，剩余可退 %d 分（%s）\n",
1449					al.Month, al.Amount, refunded, al.Amount-refunded, moneyFen(al.Amount-refunded))
1450			}
1451		}
1452	}
