1454	// --- 收款分配更正 ---
1455	
1456	func cmdBillCorrect(dir, payID, corrID, reason string, allocArgs []string) error {
1457		if strings.TrimSpace(payID) == "" {
1458			return fmt.Errorf("收款标识不能为空")
1459		}
1460		if strings.TrimSpace(corrID) == "" {
1461			return fmt.Errorf("更正标识不能为空")
1462		}
1463		if strings.TrimSpace(reason) == "" {
1464			return fmt.Errorf("更正原因不能为空")
1465		}
1466		allocs, err := parseAllocations(allocArgs)
1467		if err != nil {
1468			return err
1469		}
1470		// 分配顺序不影响更正身份：统一按月份升序保存与比较。
1471		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1472	
1473		s, err := loadStore(dir)
1474		if err != nil {
1475			return err
1476		}
1477		p, ok := s.Payments[payID]
1478		if !ok {
1479			return fmt.Errorf("收款标识 %q 不存在，无法更正分配", payID)
1480		}
1481	
1482		if existing, ok := s.Corrections[corrID]; ok {
1483			// 相同标识按目标收款、原因与新月份-金额对应关系判重（列表顺序无关）：
1484			// 内容相同返回原更正记录，不改分配、不增历史；后续更正或收款撤销
1485			// 不影响此规则。任何一项不同（含跨收款复用）均拒绝。
1486			if existing.PaymentID == payID && existing.Reason == reason && sameAllocations(existing.Allocations, allocs) {
1487				fmt.Fprintf(stdout, "更正 %q 已存在且内容相同，返回原更正记录（不改分配、不增历史）：\n\n", corrID)
1488				printCorrection(existing, s)
1489				return nil
1490			}
1491			return fmt.Errorf("更正标识 %q 已存在但内容不同（已有：收款=%s 原因=%q 新分配=%s），拒绝复用",
1492				corrID, existing.PaymentID, existing.Reason, formatAllocations(existing.Allocations))
1493		}
1494	
1495		// 新增更正只允许未撤销收款。
1496		if p.Revoked {
1497			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），不能新增分配更正", payID, p.RevokeReason)
1498		}
1499	
1500		// 首次退款后该收款的最新分配固定，拒绝新增分配更正；已有更正的相同
1501		// 重放已在上面按原记录返回，不受此限。无退款的收款仍按原规则处理。
1502		if paymentHasRefunds(s, payID) {
1503			return fmt.Errorf("收款 %q 已发生退款，最新分配已固定，拒绝新增分配更正", payID)
1504		}
1505	
1506		// 新分配合计必须等于原收款总额（不重复收钱也不多收），全程整数运算。
1507		var sum int64
1508		for _, al := range allocs {
1509			sum, err = add64(sum, al.Amount)
1510			if err != nil {
1511				return fmt.Errorf("新分配金额合计溢出有符号 64 位整数范围，拒绝更正")
1512			}
1513		}
1514		if sum != p.Total {
1515			return fmt.Errorf("新分配合计 %d 分与原收款 %q 的总额 %d 分不一致，拒绝更正", sum, payID, p.Total)
1516		}
1517		// 新分配月份须是原客户的已结算账单。
1518		for _, al := range allocs {
1519			if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
1520				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），更正只能分配到已存在账单", p.CustomerID, al.Month)
1521			}
1522		}
1523	
1524		// 以当前最新分配为起点：撤去该笔当前分配再计入新分配后，涉及月份
1525		// 均须满足 0 ≤ 实收 ≤ 应付；其他收款不变，全部合法才整笔生效。
1526		current := currentAllocations(s, p)
1527		for _, m := range unionMonths(current, allocs) {
1528			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1529			_, payable, err := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1530			if err != nil {
1531				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝更正: %w", p.CustomerID, m, err)
1532			}
1533			received, err := paymentReceived(s, p.CustomerID, m)
1534			if err != nil {
1535				return fmt.Errorf("客户 %s 的 %s 实收累计异常，拒绝更正: %w", p.CustomerID, m, err)
1536			}
1537			// 该笔收款未撤销，其实收必然包含当前分配，撤去不会变负。
1538			received -= allocAmountFor(current, m)
1539			received, err = add64(received, allocAmountFor(allocs, m))
1540			if err != nil {
1541				return fmt.Errorf("客户 %s 的 %s 更正后实收溢出有符号 64 位整数范围，拒绝更正", p.CustomerID, m)
1542			}
1543			if received > payable {
1544				return fmt.Errorf("更正后客户 %s 的 %s 实收 %d 分将超过当前应付 %d 分，拒绝更正；全部状态保持不变",
1545					p.CustomerID, m, received, payable)
1546			}
1547		}
1548	
1549		c := &correction{
1550			ID:          corrID,
1551			PaymentID:   payID,
1552			Reason:      reason,
1553			Allocations: allocs,
1554			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1555		}
1556		s.NextSeq++
1557		c.Seq = s.NextSeq
1558		s.Corrections[corrID] = c
1559	
1560		// 更正记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1561		// 一切不生效，该更正标识不被占用。
1562		if err := s.save(); err != nil {
1563			delete(s.Corrections, corrID)
1564			s.NextSeq--
1565			return err
1566		}
1567		fmt.Fprintf(stdout, "已登记收款分配更正 %q（关联收款 %q）：\n\n", corrID, payID)
1568		printCorrection(c, s)
1569		return nil
1570	}
1571	
1572	// unionMonths 返回两个分配列表涉及月份的并集，按月份升序。
1573	func unionMonths(a, b []paymentAllocation) []string {
1574		set := make(map[string]bool, len(a)+len(b))
1575		for _, al := range a {
1576			set[al.Month] = true
1577		}
1578		for _, al := range b {
1579			set[al.Month] = true
1580		}
1581		months := make([]string, 0, len(set))
1582		for m := range set {
1583			months = append(months, m)
1584		}
1585		sort.Strings(months)
1586		return months
1587	}
1588	
1589	// allocationBefore 返回一次更正发生前该收款生效的分配：上一条更正的
1590	// 新分配，或（首次更正时）收款的原始分配。
1591	func allocationBefore(s *state, c *correction) []paymentAllocation {
1592		before := s.Payments[c.PaymentID].Allocations // 载入时已校验存在
1593		var latest *correction
1594		for _, o := range s.Corrections {
1595			if o.PaymentID == c.PaymentID && o.Seq < c.Seq && (latest == nil || o.Seq > latest.Seq) {
1596				latest = o
1597			}
1598		}
1599		if latest != nil {
1600			before = latest.Allocations
1601		}
1602		return before
1603	}
