1605	// printCorrection 输出单笔更正记录：关联收款、标识、原因、完整前后分配，
1606	// 以及前后分配涉及月份的当前余额。
1607	func printCorrection(c *correction, s *state) {
1608		p := s.Payments[c.PaymentID] // 载入时已校验存在
1609		before := allocationBefore(s, c)
1610		fmt.Fprintf(stdout, "更正标识：%s\n", c.ID)
1611		fmt.Fprintf(stdout, "关联收款：%s（客户 %s，总额 %d 分（%s），备注：%s）\n",
1612			p.ID, p.CustomerID, p.Total, moneyFen(p.Total), p.Note)
1613		fmt.Fprintf(stdout, "原因：%s\n", c.Reason)
1614		fmt.Fprintf(stdout, "更正前分配：%s\n", formatAllocations(before))
1615		fmt.Fprintf(stdout, "更正后分配：%s\n", formatAllocations(c.Allocations))
1616		fmt.Fprintln(stdout, "涉及月份当前余额：")
1617		for _, m := range unionMonths(before, c.Allocations) {
1618			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1619			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1620			received, _ := paymentReceived(s, p.CustomerID, m)
1621			fmt.Fprintf(stdout, "  月份 %s：本笔分配 %d 分 → %d 分；当前应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1622				m, allocAmountFor(before, m), allocAmountFor(c.Allocations, m),
1623				payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1624		}
1625	}
