27		}
28		if endMonth <= startMonth {
29			return fmt.Errorf("暂停结束月 %s 必须晚于起月 %s（区间包含起月、不包含结束月）", endMonth, startMonth)
30		}
31		if strings.TrimSpace(reason) == "" {
32			return fmt.Errorf("暂停原因不能为空")
33		}
34	
35		s, err := loadStore(dir)
36		if err != nil {
37			return err
38		}
39		cust, ok := s.Customers[customerID]
