55				printSuspension(existing)
56				return nil
57			}
58			return fmt.Errorf("客户 %s 在 %s 已登记暂停区间（原结束月 %s，原因 %q），内容不同，暂停记录不可改写",
59				customerID, startMonth, existing.EndMonth, existing.Reason)
60		}
61	
62		// 起月须晚于该客户所有已封账月份：已封账账单不因暂停改变。
63		for _, b := range s.Bills {
64			if b.CustomerID == customerID && b.Month >= startMonth {
65				return fmt.Errorf("客户 %s 的 %s 已封账，暂停起月 %s 须晚于该客户所有已封账月份",
66					customerID, b.Month, startMonth)
67			}
68		}
69		// 同一客户的当前有效区间不得重叠（可以相接，相接视为连续暂停）：提前
70		// 恢复只缩短其他暂停的有效区间，故重叠判断使用各项的当前有效结束月；
71		// 其他客户互不影响。
72		for _, su := range s.suspensionsFor(customerID) {
73			effEnd := s.suspensionEffectiveEnd(su)
74			if startMonth < effEnd && endMonth > su.StartMonth {
75				return fmt.Errorf("新区间 %s..%s（不含结束月）与客户 %s 已登记区间 %s..%s（当前有效，不含结束月）重叠；区间可以相接但不得重叠",
76					startMonth, endMonth, customerID, su.StartMonth, effEnd)
77			}
78		}
79		// 登记前检查新区间内已导入的有效（未撤回）用量：存在任一条就拒绝并指出
80		// 冲突记录，不删除或改写任何用量；已撤回记录不参与冲突判断，可存在于
81		// 随后暂停的月份。
82		var conflicts []string
83		conflictMonths := make(map[string]bool)
84		for _, u := range s.Usage {
85			if s.isWithdrawn(u.ID) {
86				continue
87			}
88			if u.CustomerID != customerID {
89				continue
90			}
91			m := utcMonth(u.Time)
92			if monthInRange(m, startMonth, endMonth) {
93				conflicts = append(conflicts, fmt.Sprintf("用量 %s（%s，数量 %d）", u.ID, m, u.Quantity))
94				conflictMonths[m] = true
95			}
96		}
97		if len(conflicts) > 0 {
98			sort.Strings(conflicts)
