105				startMonth, endMonth, len(conflicts), strings.Join(months, "、"), strings.Join(conflicts, "、"))
106		}
107	
108		su := &suspension{
109			CustomerID: customerID,
110			StartMonth: startMonth,
111			EndMonth:   endMonth,
112			Reason:     reason,
113			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
114		}
115		s.Suspensions[key] = su
