117		// 暂停记录整体原子落盘后才报告成功；保存失败则一切不生效，
118		// 该客户该起月不被占用，可原样重试。
119		if err := s.save(); err != nil {
120			delete(s.Suspensions, key)
121			return err
122		}
123		fmt.Fprintf(stdout, "已登记暂停区间：客户 %s 自 %s（UTC 自然月，含）至 %s（不含）暂停服务，期间不接收用量、不产生月费账单：\n\n",
124			customerID, startMonth, endMonth)
125		printSuspension(su)
126		return nil
127	}
