132	// 每项暂停只能登记一次提前恢复；相同恢复月与原因的重放返回保存信息与当前
133	// 有效区间、不写盘，内容不同拒绝。其他月份已封账不妨碍登记，已有账单、
134	// 用量、方案安排和账后余额不变，不占用账后操作序号。
135	func cmdCustomerResume(dir, customerID, startMonth, resumeMonth, reason string) error {
136		if !validMonth(startMonth) {
137			return fmt.Errorf("目标暂停原起月 %q 无效，必须是 YYYY-MM 形式（如 2026-11）", startMonth)
138		}
139		if !validMonth(resumeMonth) {
140			return fmt.Errorf("恢复月 %q 无效，必须是 YYYY-MM 形式（如 2026-12）", resumeMonth)
141		}
142		if strings.TrimSpace(reason) == "" {
143			return fmt.Errorf("提前恢复原因不能为空")
144		}
145	
146		s, err := loadStore(dir)
147		if err != nil {
148			return err
149		}
150		cust, ok := s.Customers[customerID]
151		if !ok {
152			return fmt.Errorf("客户标识 %q 不存在", customerID)
153		}
154		if cust.PlanID == "" {
155			return fmt.Errorf("客户 %s 是固定单价客户（单价 %d 分），未绑定阶梯方案，不适用暂停与提前恢复", customerID, cust.Price)
156		}
157	
158		key := suspensionKey(customerID, startMonth)
159		su, ok := s.Suspensions[key]
160		if !ok {
161			return fmt.Errorf("客户 %s 自 %s 起的暂停不存在，无法登记提前恢复（目标暂停必须先以 customer suspend 登记）",
162				customerID, startMonth)
163		}
164		if existing, ok := s.SuspensionResumes[key]; ok {
165			// 以客户和原起月识别该项恢复：相同恢复月与原因的重放返回保存信息
166			// 和当前有效区间、不写盘——即使恢复月后来已结算、又登记了新的暂停
167			// 或发生方案变更也须成功，且不撤销后来的暂停；内容不同拒绝，恢复
168			// 记录不可改写或撤销。
169			if existing.ResumeMonth == resumeMonth && existing.Reason == reason {
170				fmt.Fprintf(stdout, "客户 %s 自 %s 起暂停的提前恢复已存在且内容相同，返回保存信息与当前有效区间（不写盘）：\n\n",
171					customerID, startMonth)
172				printSuspensionDetail(s, su)
