176				customerID, startMonth, existing.ResumeMonth, existing.Reason)
177		}
178	
179		// 原起月 < 恢复月 < 原结束月：恢复月必须仍在目标暂停原区间内部，
180		// 月份按 UTC 自然月解释，与操作当天无关。
181		if resumeMonth <= startMonth {
