189		r := &suspensionResume{
190			CustomerID:  customerID,
191			StartMonth:  startMonth,
192			ResumeMonth: resumeMonth,
193			Reason:      reason,
194			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
195		}
196		s.SuspensionResumes[key] = r
197	
198		// 恢复记录整体原子保存后才报告成功；保存失败则一切不生效，不占用该项
199		// 暂停的恢复登记，可原样重试。提前恢复只缩短目标区间，不改动用量、账单、
200		// 方案安排、账后余额或其他暂停。
201		if err := s.save(); err != nil {
202			delete(s.SuspensionResumes, key)
203			return err
204		}
205		fmt.Fprintf(stdout, "已登记暂停提前恢复：客户 %s 的暂停自 %s（UTC 自然月，含）起恢复服务，无需等到原结束月 %s；原暂停区间与原因永久保留，恢复记录不可改写或撤销：\n\n",
206			customerID, resumeMonth, su.EndMonth)
207		printSuspensionDetail(s, su)
208		return nil
209	}
210	
211	// printSuspension 输出一条暂停区间的原区间与原因（customer suspend 登记
212	// 与相同重放使用）。提前恢复信息由 printSuspensionDetail 展示。
213	func printSuspension(su *suspension) {
214		fmt.Fprintf(stdout, "客户：%s\n", su.CustomerID)
215		fmt.Fprintf(stdout, "暂停区间：%s（含）至 %s（不含，UTC 自然月）\n", su.StartMonth, su.EndMonth)
216		fmt.Fprintf(stdout, "原因：%s\n", su.Reason)
217	}
218	
219	// printSuspensionDetail 输出一项暂停的完整信息：原暂停区间与原因、提前恢复
220	// 信息（若有）以及当前有效区间。原区间与原因永久保留；当前有效区间在提前
221	// 恢复后缩短为 [原起月, 恢复月)。
222	func printSuspensionDetail(s *state, su *suspension) {
223		fmt.Fprintf(stdout, "客户：%s\n", su.CustomerID)
224		fmt.Fprintf(stdout, "原暂停区间：%s（含）至 %s（不含，UTC 自然月，永久保留）\n", su.StartMonth, su.EndMonth)
225		fmt.Fprintf(stdout, "原暂停原因：%s（永久保留）\n", su.Reason)
226		effEnd := s.suspensionEffectiveEnd(su)
227		if r := s.suspensionResumeOf(su); r != nil {
228			fmt.Fprintf(stdout, "提前恢复：自 %s（含，UTC 自然月）起恢复服务，恢复原因：%s（恢复记录永久保留、不可改写或撤销）\n",
229				r.ResumeMonth, r.Reason)
230			fmt.Fprintf(stdout, "当前有效区间：%s（含）至 %s（不含，恢复月起不再受该项暂停限制；仍暂停的月份不补收月费）\n",
231				su.StartMonth, effEnd)
232		} else {
233			fmt.Fprintln(stdout, "提前恢复：无")
234			fmt.Fprintf(stdout, "当前有效区间：%s（含）至 %s（不含，与原暂停区间相同）\n", su.StartMonth, effEnd)
235		}
236	}
237	
238	// describeSuspension 返回覆盖指定月份的暂停当前有效区间的简短描述，用于
239	// 错误信息。
240	func describeSuspension(s *state, customerID, month string) string {
241		for _, su := range s.suspensionsFor(customerID) {
242			effEnd := s.suspensionEffectiveEnd(su)
243			if monthInRange(month, su.StartMonth, effEnd) {
244				return fmt.Sprintf("有效区间 %s（含）至 %s（不含），原因：%s", su.StartMonth, effEnd, su.Reason)
245			}
246		}
247		return "暂停区间"
248	}
249	
250	func cmdCustomerSuspensions(dir, customerID, month string, hasMonth bool) error {
251		if hasMonth && !validMonth(month) {
252			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-11）", month)
253		}
254	
255		s, err := loadStore(dir)
256		if err != nil {
257			return err
258		}
259		cust, ok := s.Customers[customerID]
260		if !ok {
261			return fmt.Errorf("客户标识 %q 不存在", customerID)
262		}
263	
264		// 只读查询：不改写存档、不占用序号、不新增记录；成功或失败均不落盘。
265		if cust.PlanID == "" {
266			fmt.Fprintf(stdout, "客户 %s（%s）是固定单价客户（单价 %d 分），不适用按月暂停，全部月份正常服务\n",
267				cust.ID, cust.Name, cust.Price)
268			if hasMonth {
269				fmt.Fprintf(stdout, "月份 %s：不适用暂停（固定单价客户正常服务）\n", month)
270			}
271			return nil
272		}
273	
274		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
275		list := s.suspensionsFor(customerID)
276		if len(list) == 0 {
277			fmt.Fprintln(stdout, "暂停区间：无（全部 UTC 自然月正常服务）")
278		} else {
279			fmt.Fprintln(stdout, "暂停区间（按起月升序；原区间与原因永久保留，另展示提前恢复信息与当前有效区间）：")
280			for i, su := range list {
281				effEnd := s.suspensionEffectiveEnd(su)
282				fmt.Fprintf(stdout, "  %d. %s（含）至 %s（不含），原因：%s\n",
283					i+1, su.StartMonth, su.EndMonth, su.Reason)
284				if r := s.suspensionResumeOf(su); r != nil {
285					fmt.Fprintf(stdout, "     提前恢复：自 %s（含，UTC 自然月）起恢复服务，恢复原因：%s（永久保留、不可改写或撤销）\n",
286						r.ResumeMonth, r.Reason)
287					fmt.Fprintf(stdout, "     当前有效区间：%s（含）至 %s（不含，恢复月起正常服务）\n", su.StartMonth, effEnd)
288				} else {
289					fmt.Fprintf(stdout, "     提前恢复：无；当前有效区间：%s（含）至 %s（不含，与原区间相同）\n",
290						su.StartMonth, effEnd)
291				}
292			}
293		}
294		if hasMonth {
295			var hit *suspension
296			for _, su := range list {
297				if monthInRange(month, su.StartMonth, s.suspensionEffectiveEnd(su)) {
298					hit = su
299					break
300				}
301			}
302			if hit != nil {
303				r := s.suspensionResumeOf(hit)
304				fmt.Fprintf(stdout, "月份 %s：已暂停（处于当前有效区间 %s（含）至 %s（不含）），原暂停原因：%s",
305					month, hit.StartMonth, s.suspensionEffectiveEnd(hit), hit.Reason)
306				if r != nil {
307					// 当前有效区间内的月份不可能晚于恢复月；保留恢复信息以便核对。
308					fmt.Fprintf(stdout, "；该暂停已登记自 %s（含）起提前恢复", r.ResumeMonth)
309				}
310				fmt.Fprintln(stdout)
311			} else {
312				// 实际未暂停时区分：原本在暂停原区间内但因提前恢复而释放的月份，
313				// 与从未被任何暂停覆盖的月份。
314				var released *suspension
315				for _, su := range list {
316					if r := s.suspensionResumeOf(su); r != nil &&
317						monthInRange(month, su.StartMonth, su.EndMonth) && month >= r.ResumeMonth {
318						released = su
319						break
320					}
321				}
322				if released != nil {
323					r := s.suspensionResumeOf(released)
324					fmt.Fprintf(stdout, "月份 %s：未暂停（原暂停 %s（含）至 %s（不含）已登记提前恢复，自 %s（含）起恢复服务，恢复原因：%s，正常服务）\n",
325						month, released.StartMonth, released.EndMonth, r.ResumeMonth, r.Reason)
326				} else {
327					fmt.Fprintf(stdout, "月份 %s：未暂停（不在任何暂停当前有效区间内，正常服务）\n", month)
328				}
329			}
330		}
331		return nil
332	}
