24	// 每条原用量只能更正一次，以原标识识别该项更正。相同新标识、客户、解析后
25	// 的时间点、数量与原因重放，返回原更正及两条记录当前状态，不写盘；任一项
26	// 不同拒绝。替代记录可继续更正或按原规则撤回；后来封账、暂停、方案变化或
27	// 替代记录已撤回，都不能阻止相同重放，也不能恢复任何记录。
28	
29	func cmdUsageCorrect(dir, origID, newID, newCustomerID, newTimeText, qtyText, reason string) error {
30		if strings.TrimSpace(origID) == "" {
31			return fmt.Errorf("原用量标识不能为空")
32		}
