58	
59		// 幂等重放优先于一切首次校验：以原标识识别该项更正。后来封账、暂停、
60		// 方案变化或替代记录已撤回，都不能阻止相同重放，也不能恢复任何记录。
61		if uc, ok := s.UsageCorrections[origID]; ok {
62			if uc.ReplacementID == newID && uc.NewCustomerID == newCustomerID &&
63				uc.NewQuantity == qty && uc.Reason == reason {
