69				}
70			}
71			return fmt.Errorf("用量 %q 已更正（替代记录 %q，客户 %s，时间 %s，数量 %d，原因 %q），"+
72				"新标识、客户、解析后的时间点、数量或原因任一项不同即拒绝；每条原用量只能更正一次，更正不可撤销",
73				origID, uc.ReplacementID, uc.NewCustomerID, uc.NewTime, uc.NewQuantity, uc.Reason)
