114		// UTC 月份的有效方案计价，检查分段金额不溢出。月累计溢出仍由结算把关。
115		repl := &usageRecord{ID: newID, CustomerID: newCustomerID, Time: strings.TrimSpace(newTimeText), Quantity: qty}
116		if newCust.PlanID == "" {
117			if _, err := mul64(qty, newCust.Price); err != nil {
