121		} else {
122			planID := s.effectivePlanID(newCust, newMonth)
123			if _, err := tieredPrice(s.Plans[planID].Tiers, []*usageRecord{repl}); err != nil {
124				return fmt.Errorf("按客户 %s 的 %s 月有效方案 %q 对新数量单条从零计价失败：%v；拒绝更正",
125					newCustomerID, newMonth, planID, err)
126			}
127		}
128	
129		// 三项变更先在内存完成，再整体原子保存：原记录撤回标记、替代记录、
130		// 更正关联。原内容不改写，不占用账后操作序号。
131		now := time.Now().UTC().Format(time.RFC3339)
132		s.Withdrawals[origID] = &withdrawal{UsageID: origID, Reason: reason, CreatedAt: now}
133		s.Usage[newID] = repl
134		uc := &usageCorrection{
135			UsageID:       origID,
136			ReplacementID: newID,
137			NewCustomerID: newCustomerID,
138			NewTime:       repl.Time,
139			NewQuantity:   qty,
140			Reason:        reason,
141			CreatedAt:     now,
142		}
143		s.UsageCorrections[origID] = uc
144	
145		if err := s.save(); err != nil {
146			// 保存失败：三项全部回滚，全部业务状态不变，失败不占用新标识，
147			// 原记录不留下撤回标记或关联，可原样重试。
148			delete(s.Withdrawals, origID)
149			delete(s.Usage, newID)
150			delete(s.UsageCorrections, origID)
151			return err
152		}
153	
154		fmt.Fprintf(stdout, "已更正用量 %q：原记录按更正原因标记撤回，替代记录 %q 已登记，关联永久保存；原内容不可改写、更正不可撤销、不占用账后操作序号：\n\n",
155			origID, newID)
156		printUsageCorrection(s, uc)
157		return nil
158	}
159	
160	// predecessorCorrection 返回以指定用量为替代记录的更正（即该记录的直接
161	// 前身关联）；无前身时返回 nil。
162	func predecessorCorrection(s *state, usageID string) *usageCorrection {
163		for _, uc := range s.UsageCorrections {
164			if uc.ReplacementID == usageID {
