1	package main
2	
3	import (
4		"fmt"
5		"strings"
6		"time"
7	)
8	
9	// 本文件实现未封账用量的撤回（usage withdraw）与按用量标识的只读查询
10	// （usage show），用于纠正误导入的记录并保留追溯信息。撤回适用于固定单价
11	// 与阶梯客户：首次撤回须找到原记录，且按原时间换算的 UTC 自然月尚未封账；
12	// 已封账用量拒绝撤回，不改变账单或账后余额。成功后原客户、时间、数量与标识
13	// 永久保留，仅追加撤回状态与原因；撤回不可恢复，标识不可复用，相同内容的
14	// 导入重放仍按原记录判重跳过、不会恢复记录。撤回只作用于该条记录，不产生
15	// 账后流水事件，也不占用全局操作序号。
16	
17	func cmdUsageWithdraw(dir, usageID, reason string) error {
18		if strings.TrimSpace(usageID) == "" {
19			return fmt.Errorf("用量标识不能为空")
20		}
21		if strings.TrimSpace(reason) == "" {
22			return fmt.Errorf("撤回原因不能为空")
23		}
24	
25		s, err := loadStore(dir)
26		if err != nil {
27			return err
28		}
29		u, ok := s.Usage[usageID]
30		if !ok {
31			return fmt.Errorf("用量标识 %q 不存在，无法撤回", usageID)
32		}
33	
34		if w, ok := s.Withdrawals[usageID]; ok {
35			// 同一用量相同原因的重复撤回：返回原记录且不写盘——即使后来该月
36			// 已封账或暂停仍成功；改用其他原因则拒绝，撤回不可恢复。
37			if w.Reason == reason {
38				fmt.Fprintf(stdout, "用量 %q 已撤回且撤回原因相同，返回原记录（不写盘）：\n\n", usageID)
39				printUsageRecord(s, u)
40				return nil
41			}
42			return fmt.Errorf("用量 %q 已撤回（撤回原因 %q），改用其他原因重复撤回被拒绝；撤回不可恢复", usageID, w.Reason)
43		}
44	
45		// 首次撤回：按原记录时间换算的 UTC 自然月尚未封账才允许；已封账用量
46		// 拒绝撤回，不改变账单或账后余额。
47		month := utcMonth(u.Time)
48		if s.sealed(u.CustomerID, month) {
49			return fmt.Errorf("用量 %q 属于客户 %s 的 %s（UTC 自然月），该月已封账，拒绝撤回；账单与账后余额不变",
50				usageID, u.CustomerID, month)
51		}
52	
53		w := &withdrawal{
54			UsageID:   usageID,
55			Reason:    reason,
56			CreatedAt: time.Now().UTC().Format(time.RFC3339),
57		}
58		s.Withdrawals[usageID] = w
59	
60		// 撤回状态与原因整体原子保存后才报告成功；保存失败则一切不生效，
61		// 不留下撤回标记，可原样重试。
62		if err := s.save(); err != nil {
63			delete(s.Withdrawals, usageID)
64			return err
65		}
66		fmt.Fprintf(stdout, "已撤回用量 %q（客户 %s，%s，数量 %d），撤回不可恢复、标识不可复用；该记录不再参与结算与冲突检查：\n\n",
67			usageID, u.CustomerID, month, u.Quantity)
68		printUsageRecord(s, u)
69		return nil
70	}
71	
72	func cmdUsageShow(dir, usageID string) error {
73		if strings.TrimSpace(usageID) == "" {
74			return fmt.Errorf("用量标识不能为空")
75		}
76	
77		s, err := loadStore(dir)
78		if err != nil {
79			return err
80		}
81		u, ok := s.Usage[usageID]
82		if !ok {
83			return fmt.Errorf("用量标识 %q 不存在", usageID)
84		}
85		// 只读查询：不改写存档、不占用序号、不新增记录；成功或失败均不落盘。
86		printUsageRecord(s, u)
87		return nil
88	}
89	
90	// printUsageRecord 输出一条用量记录的原始内容（标识、客户、时间、数量）、
91	// 换算后的 UTC 自然月，以及是否撤回与撤回原因；此外展示该记录在用量更正链
92	// 上的直接前身、后继及对应更正原因，无任何更正关联时明确说明。
93	func printUsageRecord(s *state, u *usageRecord) {
94		cust := s.Customers[u.CustomerID] // 载入时已校验存在
95		fmt.Fprintf(stdout, "用量标识：%s\n", u.ID)
96		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
97		fmt.Fprintf(stdout, "时间：%s\n", u.Time)
98		fmt.Fprintf(stdout, "UTC 月份：%s（UTC 自然月，左闭右开）\n", utcMonth(u.Time))
99		fmt.Fprintf(stdout, "数量：%d\n", u.Quantity)
100		if w, ok := s.Withdrawals[u.ID]; ok {
101			fmt.Fprintf(stdout, "当前状态：已撤回（撤回原因：%s；不参与结算与冲突检查，不可恢复）\n", w.Reason)
102		} else {
103			fmt.Fprintln(stdout, "当前状态：有效（参与结算与冲突检查）")
104		}
105		// 直接前身：本记录是哪条原用量的更正替代。
106		if pred := predecessorCorrection(s, u.ID); pred != nil {
107			fmt.Fprintf(stdout, "直接前身：%s（由用量更正替代而来，更正原因：%s）\n", pred.UsageID, pred.Reason)
108		} else {
109			fmt.Fprintln(stdout, "直接前身：无（不是任何用量更正的替代记录）")
110		}
111		// 直接后继：本记录被更正后产生的替代记录。
112		if succ := successorCorrection(s, u.ID); succ != nil {
113			fmt.Fprintf(stdout, "直接后继：%s（本记录已被用量更正替代，更正原因：%s；更正不可撤销）\n", succ.ReplacementID, succ.Reason)
114		} else {
115			fmt.Fprintln(stdout, "直接后继：无（本记录未曾被更正）")
116		}
117	}
