1	package main
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	// 本文件实现方案变更撤销（plan revoke）：取消误登记的价格安排并保留追溯。
11	//
12	// 撤销接受客户、目标变更的 YYYY-MM 生效月和非空原因，仅限阶梯客户且目标
13	// 变更必须存在。原变更内容（目标方案与原因）永久保留，只追加不可撤销的
14	// 撤销记录；每项变更只能撤销一次，撤销不占用账后操作序号。
15	//
16	// 有效方案只考虑未撤销变更：撤销目标后，自其生效月起沿用此前最后一项未
17	// 撤销变更的方案，无则用初始方案，直到其后下一项未撤销变更的生效月前；
18	// 没有后一项则覆盖之后所有月份。连续撤销按当时安排确定受影响区间；其他
19	// 变更和暂停、提前恢复记录不改动。
20	//
21	// 首次撤销时，受影响区间内有已封账账单则拒绝，区间外已封账不妨碍登记。
22	// 区间内有效用量按撤销后方案逐条从零预检用量费，任一条溢出有符号 64 位
23	// 范围则整项拒绝并指出记录，已撤回用量不参与；月累计及月费加用量费溢出
24	// 仍由结算拒绝且不封账。用量内容、已有账单快照与账后余额保持不变。
25	
26	func cmdPlanRevoke(dir, customerID, month, reason string) error {
27		if !validMonth(month) {
28			return fmt.Errorf("目标变更生效月 %q 无效，必须是 YYYY-MM 形式（如 2026-11）", month)
29		}
30		if strings.TrimSpace(reason) == "" {
31			return fmt.Errorf("撤销原因不能为空")
32		}
33	
34		s, err := loadStore(dir)
35		if err != nil {
36			return err
37		}
38		cust, ok := s.Customers[customerID]
39		if !ok {
40			return fmt.Errorf("客户标识 %q 不存在", customerID)
41		}
42		if cust.PlanID == "" {
43			return fmt.Errorf("客户 %s 是固定单价客户，未绑定阶梯方案，不能撤销方案变更", customerID)
44		}
45	
46		key := planChangeKey(customerID, month)
47		ch, ok := s.PlanChanges[key]
48		if !ok {
49			return fmt.Errorf("客户 %s 在 %s 的方案变更不存在，无法撤销（目标必须是已登记的方案变更）", customerID, month)
50		}
51	
52		if rv, ok := s.PlanChangeRevocations[key]; ok {
53			// 以客户与目标生效月识别撤销：相同原因的重放返回原撤销与当前安排、
54			// 不写盘——即使后来相关月份已封账、追加了新变更或撤销了其他项也
55			// 成功；换原因拒绝，撤销记录不可改写、不可撤销。
56			if rv.Reason == reason {
57				fmt.Fprintf(stdout, "客户 %s 在 %s 的方案变更撤销已存在且原因相同，返回原撤销与当前安排（不写盘）：\n\n",
58					customerID, month)
59				printPlanRevocation(s, rv, ch)
60				return nil
61			}
62			return fmt.Errorf("客户 %s 在 %s 的方案变更已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝；撤销记录不可改写、不可撤销",
63				customerID, month, rv.Reason)
64		}
65	
66		// 受影响区间 [month, end)：自目标生效月（含）起，直到其后下一项未撤销
67		// 变更的生效月前；没有后一项则覆盖之后所有月份（end 为空）。连续撤销时
68		// 该区间按当时安排（目标本身仍有效）确定。
69		end := s.nextActiveChangeMonth(customerID, month)
70	
71		// 首次撤销时，受影响区间内有已封账账单则拒绝：已封账账单快照不因撤销
72		// 改变，区间外已封账不妨碍登记。
73		var sealed []string
74		for _, b := range s.Bills {
75			if b.CustomerID == customerID && b.Month >= month && (end == "" || b.Month < end) {
76				sealed = append(sealed, b.Month)
77			}
78		}
79		if len(sealed) > 0 {
80			sort.Strings(sealed)
81			return fmt.Errorf("客户 %s 的方案变更 %s 受影响区间 %s 内已有封账账单（月份 %s），拒绝撤销；账单快照与账后余额保持不变",
82				customerID, month, describeMonthRange(month, end), strings.Join(sealed, "、"))
83		}
84	
85		// 区间内有效（未撤回）用量按撤销后方案逐条从零预检用量费：任一条按其
86		// UTC 月份撤销后有效方案计价溢出有符号 64 位范围则整项拒绝并指出记录；
87		// 已撤回用量不参与。月累计及月费加用量费溢出仍由结算把关。
88		var ids []string
89		for _, u := range s.Usage {
90			if s.isWithdrawn(u.ID) {
91				continue
92			}
93			if u.CustomerID == customerID {
94				m := utcMonth(u.Time)
95				if m >= month && (end == "" || m < end) {
96					ids = append(ids, u.ID)
97				}
98			}
99		}
100		sort.Strings(ids)
101		for _, id := range ids {
102			u := s.Usage[id]
103			m := utcMonth(u.Time)
104			planID := s.effectivePlanIDIgnoring(cust, m, key)
105			p := s.Plans[planID] // 载入时已校验存在
106			rec := *u
107			if _, err := tieredPrice(p.Tiers, []*usageRecord{&rec}); err != nil {
108				return fmt.Errorf("用量 %s（%s，数量 %d）按撤销后方案 %q 单条从零计价失败：%v；整项撤销拒绝，用量、账单与账后余额均不修改",
109					u.ID, m, u.Quantity, planID, err)
110			}
111		}
112	
113		rv := &planChangeRevocation{
114			CustomerID: customerID,
115			Month:      month,
116			Reason:     reason,
117			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
118		}
119		s.PlanChangeRevocations[key] = rv
120	
121		// 撤销记录整体原子落盘后才报告成功；保存失败则一切不生效，不占用该项
122		// 变更的撤销登记，可原样重试。撤销只追加记录，不改动用量内容、已有账单
123		// 快照、账后余额、其他变更、暂停与提前恢复记录。
124		if err := s.save(); err != nil {
125			delete(s.PlanChangeRevocations, key)
126			return err
127		}
128		fmt.Fprintf(stdout, "已撤销方案变更：客户 %s 自 %s（UTC 自然月，含）起的目标安排取消，原变更内容永久保留，撤销记录不可撤销、不占用账后操作序号：\n\n",
129			customerID, month)
130		printPlanRevocation(s, rv, ch)
131		return nil
132	}
